// Generated from readable original Dialog TextAssets (Wife*_FindDialogue*): roaming encounter stories, numbered text replay only.
export default {"scenes":[{"id":"FindWife2_1","characterId":"wife_2","step":"1","lines":[{"number":1,"text":"Whoops! The goods are falling down!! Wow, thanks for helping pick them up. Mom said to thank the people who helped me, so here you are! Hee hee~","sourceKey":"Dialog:context:Wife2_FindDialogue1_1","speaker":null}]},{"id":"FindWife2_2","characterId":"wife_2","step":"2","lines":[{"number":1,"text":"It's you again! You really helped me a lot last time! Oh? You come here this time to play with me? I'd like to but I have to help my mum out first.  How about this? I'll come to {playerName} right after I finish!","sourceKey":"Dialog:context:Wife2_FindDialogue2_1","speaker":null}]},{"id":"FindWife2_3","characterId":"wife_2","step":"3","lines":[{"number":1,"text":"The work is all done! Hey, according to our agreement, I'll come to you, then we'll play~ Come on!","sourceKey":"Dialog:context:Wife2_FindDialogue3_1","speaker":null}]},{"id":"FindWife2_4","characterId":"wife_2","step":"4","lines":[{"number":1,"text":"This is \"Goblin Fruit Shop\"... Miss, how much are the fruits?","sourceKey":"Dialog:context:Wife2_FindDialogue4_1","speaker":"{playerName}"},{"number":2,"text":"Look at the sign. The prices are all listed~","sourceKey":"Dialog:context:Wife2_FindDialogue4_2","speaker":"???"},{"number":3,"text":"While you were carefully selecting fruits, the Goblin girl was also curiously observing you.","sourceKey":"Dialog:context:Wife2_FindDialogue4_3","speaker":null},{"number":4,"text":"It's so kind of you. This is the first time someone called me miss.","sourceKey":"Dialog:context:Wife2_FindDialogue4_4","speaker":"???"},{"number":5,"text":"Huh? That's not some big deal. Could you please give me some of these?","sourceKey":"Dialog:context:Wife2_FindDialogue4_5","speaker":"{playerName}"},{"number":6,"text":"And this, this, and this, a little more of each.","sourceKey":"Dialog:context:Wife2_FindDialogue4_6","speaker":"{playerName}"},{"number":7,"text":"Eat so much all by yourself... You have a really good appetite!","sourceKey":"Dialog:context:Wife2_FindDialogue4_7","speaker":null},{"number":8,"text":"(Buying this much is definitely to gift friends. But since she said that...)","sourceKey":"Dialog:context:Wife2_FindDialogue4_8","speaker":"{playerName}"},{"number":9,"text":"Yeah, since I'm buying such a lot, can you give me a discount?","sourceKey":"Dialog:context:Wife2_FindDialogue4_9","speaker":"{playerName}"},{"number":10,"text":"Wow, wow...! Not only are you very gentle and eat a lot, but you're also very thrifty!","sourceKey":"Dialog:context:Wife2_FindDialogue4_10","speaker":"???"},{"number":11,"text":"No problem, of course! I can make it even cheaper for you!!","sourceKey":"Dialog:context:Wife2_FindDialogue4_11","speaker":"???"},{"number":12,"text":"Huh? Little girl, you're so generous. Thanks~","sourceKey":"Dialog:context:Wife2_FindDialogue4_12","speaker":"{playerName}"},{"number":13,"text":"You didn't think about why the Goblin girl was so warm and left with the fruits in satisfaction.","sourceKey":"Dialog:context:Wife2_FindDialogue4_13","speaker":null},{"number":14,"text":"After you left, the girl couldn't suppress her excitement anymore...","sourceKey":"Dialog:context:Wife2_FindDialogue4_14","speaker":null},{"number":15,"text":"Being in Drakenberg for so long, I have once thought I may never find someone so considerate, reliable, and trustworthy again.","sourceKey":"Dialog:context:Wife2_FindDialogue4_15","speaker":"???"},{"number":16,"text":"I didn't expect to meet someone that fits all my dream today.","sourceKey":"Dialog:context:Wife2_FindDialogue4_16","speaker":"???"},{"number":17,"text":"Mom, Dad - come quickly - I've found the person I want to marry!","sourceKey":"Dialog:context:Wife2_FindDialogue4_17","speaker":"???"},{"number":18,"text":"But today, I have met a mushroom that fits all my dreams!","sourceKey":"Dialog:context:Wife2_FindDialogue4_18","speaker":"???"},{"number":19,"text":"Mom and Dad - come quickly - I've found the person I want to marry!","sourceKey":"Dialog:context:Wife2_FindDialogue4_19","speaker":"???"},{"number":20,"text":"You pass by a shop.","sourceKey":"Dialog:context:Wife2_FindDialogue4_Text","speaker":null}]},{"id":"FindWife2_4b","characterId":"wife_2","step":"4b","lines":[{"number":1,"text":"In the bustling market, you notice a small stall with few customers displaying some very ordinary-looking flowers.","sourceKey":"Dialog:context:Wife2_FindDialogue4b_1","speaker":null},{"number":2,"text":"(This is the only place on the street with so few customers... A florist, is it? Why only one type of flower, it's so strange.)","sourceKey":"Dialog:context:Wife2_FindDialogue4b_2","speaker":"{playerName}"},{"number":3,"text":"Ah! A customer! Come take a look at my flowers, they were all hand-picked this morning~","sourceKey":"Dialog:context:Wife2_FindDialogue4b_3","speaker":"???"},{"number":4,"text":"(These flowers are all blooming beautifully and are very high quality. Maybe they just aren't being presented well.)","sourceKey":"Dialog:context:Wife2_FindDialogue4b_4","speaker":"{playerName}"},{"number":5,"text":"Hmm... they do seem quite fresh. I'll take some.","sourceKey":"Dialog:context:Wife2_FindDialogue4b_5","speaker":"{playerName}"},{"number":6,"text":"Great! You're my first customer today~","sourceKey":"Dialog:context:Wife2_FindDialogue4b_6","speaker":"???"},{"number":7,"text":"These flowers aren't of a particularly rare species, but they're blooming beautifully, they must have been taken care of very diligently.","sourceKey":"Dialog:context:Wife2_FindDialogue4b_7","speaker":"{playerName}"},{"number":8,"text":"Wow... Hehe~ I planted them all myself, this is the first time someone has praised them... Thank you so much!","sourceKey":"Dialog:context:Wife2_FindDialogue4b_8","speaker":"???"},{"number":9,"text":"But the presentation isn't very good, look here— there's still mud on the stems.","sourceKey":"Dialog:context:Wife2_FindDialogue4b_9","speaker":"{playerName}"},{"number":10,"text":"If you cleaned them up a bit, I bet people would be more willing to buy them.","sourceKey":"Dialog:context:Wife2_FindDialogue4b_10","speaker":"{playerName}"},{"number":11,"text":"Ah! That makes sense... I'll give it a try!","sourceKey":"Dialog:context:Wife2_FindDialogue4b_11","speaker":"???"},{"number":12,"text":"The girl washes the flowers. The flowers look much better with water droplets clinging to their leaves, and customers begin to arrive one after another.","sourceKey":"Dialog:context:Wife2_FindDialogue4b_12","speaker":null},{"number":13,"text":"I've never sold this well before! Just a few more customers and my stock will be completely sold out... This is great! I can buy bread to eat today!","sourceKey":"Dialog:context:Wife2_FindDialogue4b_13","speaker":"???"},{"number":14,"text":"(She must be a bread enthusiast to be this happy.) Why don't you sell the rest to me? I just happen to need some decorations for my new home.","sourceKey":"Dialog:context:Wife2_FindDialogue4b_14","speaker":"{playerName}"},{"number":15,"text":"R-Really!? Thank you so much... I'll wrap them up for you right away!","sourceKey":"Dialog:context:Wife2_FindDialogue4b_15","speaker":"???"},{"number":16,"text":"Um, you really helped me out a lot today... My name is Charlotte, may I ask what your name is?","sourceKey":"Dialog:context:Wife2_FindDialogue4b_16","speaker":"???"},{"number":17,"text":"Just call me {playerName}. It's nothing, I just really liked the flowers you grow.","sourceKey":"Dialog:context:Wife2_FindDialogue4b_17","speaker":"{playerName}"},{"number":18,"text":"Hehe... {playerName}... Thanks again! Ah, look at the time! I better run before the discount bread is all gone, goodbye!!","sourceKey":"Dialog:context:Wife2_FindDialogue4b_18","speaker":"Charlotte"},{"number":19,"text":"Charlotte packs up her things and waves goodbye to you.","sourceKey":"Dialog:context:Wife2_FindDialogue4b_19","speaker":null},{"number":20,"text":"Such an energetic young girl... Is she the only one managing the stall? That's a lot of work...","sourceKey":"Dialog:context:Wife2_FindDialogue4b_20","speaker":"{playerName}"},{"number":21,"text":"You've been helping Charlotte with her business all day, haven't you? That was very kind-hearted of you.","sourceKey":"Dialog:context:Wife2_FindDialogue4b_21","speaker":"Nearby Vendor"},{"number":22,"text":"The child is quite pitiful, she arrives early in the morning from some faraway place to set up her stall, and she never earns much money...","sourceKey":"Dialog:context:Wife2_FindDialogue4b_22","speaker":"Nearby Vendor"},{"number":23,"text":"She often doesn't even have time for a full meal, and no one has ever seen anyone resembling a family member supporting her. *Sigh* Living alone at such a young age...","sourceKey":"Dialog:context:Wife2_FindDialogue4b_23","speaker":"Nearby Vendor"},{"number":24,"text":"(I see... No wonder a bit of bread was able to make her so happy... She's living such a difficult life.)","sourceKey":"Dialog:context:Wife2_FindDialogue4b_24","speaker":"{playerName}"},{"number":25,"text":"(And no family...?)","sourceKey":"Dialog:context:Wife2_FindDialogue4b_25","speaker":"{playerName}"}]},{"id":"FindWife2_5","characterId":"wife_2","step":"5","lines":[{"number":1,"text":"The enthusiastic Goblin girl stops you.","sourceKey":"Dialog:context:Wife2_FindDialogue5_1","speaker":null},{"number":2,"text":"Hello, customer last time! I finally find you again!","sourceKey":"Dialog:context:Wife2_FindDialogue5_2","speaker":"Charlotte"},{"number":3,"text":"I'm Charlotte! I want to become your family!","sourceKey":"Dialog:context:Wife2_FindDialogue5_3","speaker":null},{"number":4,"text":"...What???","sourceKey":"Dialog:context:Wife2_FindDialogue5_4","speaker":"{playerName}"},{"number":5,"text":"I think you're my perfect match. I've already told my parents and they agreed too!","sourceKey":"Dialog:context:Wife2_FindDialogue5_5","speaker":"Charlotte"},{"number":6,"text":"Wait, this is too sudden...","sourceKey":"Dialog:context:Wife2_FindDialogue5_6","speaker":"{playerName}"},{"number":7,"text":"A middle-aged goblin couple walked out of the fruit shop, smiling at you.","sourceKey":"Dialog:context:Wife2_FindDialogue5_7","speaker":null},{"number":8,"text":"Hey, you are truly the one my daughter into, not bad.","sourceKey":"Dialog:context:Wife2_FindDialogue5_8","speaker":"Goblin father"},{"number":9,"text":"After you finish the wedding, this shop will be given to you~","sourceKey":"Dialog:context:Wife2_FindDialogue5_9","speaker":"Mother goblin"},{"number":10,"text":"Handing over my daughter and business to a young man as reliable as you, her father and I can rest assured~","sourceKey":"Dialog:context:Wife2_FindDialogue5_10","speaker":"Mother goblin"},{"number":11,"text":"Th-thank you... but this is really not something I can agree to right away...","sourceKey":"Dialog:context:Wife2_FindDialogue5_11","speaker":"{playerName}"},{"number":12,"text":"Charlotte stopped her slightly anxious parents.","sourceKey":"Dialog:context:Wife2_FindDialogue5_12","speaker":null},{"number":13,"text":"Mom and Dad, for {playerName}, this might be a bit sudden.","sourceKey":"Dialog:context:Wife2_FindDialogue5_13","speaker":"Charlotte"},{"number":14,"text":"The goblin girl turned around and looked at you expectantly.","sourceKey":"Dialog:context:Wife2_FindDialogue5_14","speaker":null},{"number":15,"text":"Please go back and consider it, I will wait for your answer.","sourceKey":"Dialog:context:Wife2_FindDialogue5_15","speaker":"Charlotte"},{"number":16,"text":"You come to \"Goblin Fruit Shop\" again.","sourceKey":"Dialog:context:Wife2_FindDialogue5_Text","speaker":null}]},{"id":"FindWife2_5b","characterId":"wife_2","step":"5b","lines":[{"number":1,"text":"Early in the morning, you see Charlotte at her stall again.","sourceKey":"Dialog:context:Wife2_FindDialogue5b_1","speaker":null},{"number":2,"text":"She looks as energetic as ever, but the flowers in her stall are all messed up and some of the petals look damaged.","sourceKey":"Dialog:context:Wife2_FindDialogue5b_2","speaker":null},{"number":3,"text":"Charlotte? What happened to your flowers today...?","sourceKey":"Dialog:context:Wife2_FindDialogue5b_3","speaker":"{playerName}"},{"number":4,"text":"{playerName}? Good morning~ I got up early today, I wanted to pick more flowers to give to you as thanks for your help before~","sourceKey":"Dialog:context:Wife2_FindDialogue5b_4","speaker":"Charlotte"},{"number":5,"text":"But... the road to Drakenberg from my home is dark at night and I accidentally fell... and the flowers...","sourceKey":"Dialog:context:Wife2_FindDialogue5b_5","speaker":"Charlotte"},{"number":6,"text":"It's all my own clumsiness, and now they probably won't sell... let alone make a fitting gift for you...","sourceKey":"Dialog:context:Wife2_FindDialogue5b_6","speaker":"Charlotte"},{"number":7,"text":"Charlotte...","sourceKey":"Dialog:context:Wife2_FindDialogue5b_7","speaker":"{playerName}"},{"number":8,"text":"... Ah! But why am I telling you all this!","sourceKey":"Dialog:context:Wife2_FindDialogue5b_8","speaker":"Charlotte"},{"number":9,"text":"Don't worry about it, you should go somewhere else today~ Next time, I'll bring you an even better gift!","sourceKey":"Dialog:context:Wife2_FindDialogue5b_9","speaker":"Charlotte"},{"number":10,"text":"Charlotte sees you off, but you don't go far from her stall.","sourceKey":"Dialog:context:Wife2_FindDialogue5b_10","speaker":null},{"number":11,"text":"Freshly picked flowers~! Come and pick your favorite~!","sourceKey":"Dialog:context:Wife2_FindDialogue5b_11","speaker":"Charlotte"},{"number":12,"text":"As Charlotte predicted, despite her continuous efforts to sell her flowers, no one shows any interest.","sourceKey":"Dialog:context:Wife2_FindDialogue5b_12","speaker":null},{"number":13,"text":"By the time it's evening, Charlotte hasn't sold a single flower.","sourceKey":"Dialog:context:Wife2_FindDialogue5b_13","speaker":null},{"number":14,"text":"Uh oh... looks like I'll have to go hungry today... It's okay! I'll just have to tough it out!","sourceKey":"Dialog:context:Wife2_FindDialogue5b_14","speaker":"Charlotte"},{"number":15,"text":"You walk over to Charlotte's stall.","sourceKey":"Dialog:context:Wife2_FindDialogue5b_15","speaker":null},{"number":16,"text":"There's still some time before the market closes, it's too early to give up now.","sourceKey":"Dialog:context:Wife2_FindDialogue5b_16","speaker":"{playerName}"},{"number":17,"text":"{playerName}!? You're still here... My flowers, I'm sure no one will buy them.","sourceKey":"Dialog:context:Wife2_FindDialogue5b_17","speaker":"Charlotte"},{"number":18,"text":"They're difficult to sell one by one, but...","sourceKey":"Dialog:context:Wife2_FindDialogue5b_18","speaker":"{playerName}"},{"number":19,"text":"You carefully select the flowers in better condition, skillfully wrap them into a bouquet, and place them in a prominent position on the stall.","sourceKey":"Dialog:context:Wife2_FindDialogue5b_19","speaker":null},{"number":20,"text":"... Even if it's not perfect, as long as you showcase the most beautiful items you have, there's sure to be someone who appreciates it.","sourceKey":"Dialog:context:Wife2_FindDialogue5b_20","speaker":"{playerName}"},{"number":21,"text":"You help Charlotte promote her goods, and soon the simple bouquet you prepared is purchased by a couple.","sourceKey":"Dialog:context:Wife2_FindDialogue5b_21","speaker":null},{"number":22,"text":"I-I sold one... with your help again. I wanted to thank you, but only ended up causing you trouble again...","sourceKey":"Dialog:context:Wife2_FindDialogue5b_22","speaker":"Charlotte"},{"number":23,"text":"It really pains me to see someone going hungry— especially a girl like you.","sourceKey":"Dialog:context:Wife2_FindDialogue5b_23","speaker":"{playerName}"},{"number":24,"text":"What do you think, can you make it to the bakery before it closes? Hurry over, and make sure to eat enough.","sourceKey":"Dialog:context:Wife2_FindDialogue5b_24","speaker":"{playerName}"},{"number":25,"text":"... Okay! I promise to have a good meal! Hehe~","sourceKey":"Dialog:context:Wife2_FindDialogue5b_25","speaker":"Charlotte"}]},{"id":"FindWife2_6","characterId":"wife_2","step":"6","lines":[{"number":1,"text":"Hey, it's {playerName}! I used the methods you taught me and now I have a lot more regular customers~ Hehe~","sourceKey":"Dialog:context:Wife2_FindDialogue6_1","speaker":"Charlotte"}]},{"id":"FindWife2_7","characterId":"wife_2","step":"7","lines":[{"number":1,"text":"Here you are~ I have some freshly baked bread, it smells so good! Would you like to have some too?","sourceKey":"Dialog:context:Wife2_FindDialogue7_1","speaker":"Charlotte"}]},{"id":"FindWife2_After","characterId":"wife_2","step":"After","lines":[{"number":1,"text":"I used to work here alone. Today I came to shop with {playerName}. It's really interesting~","sourceKey":"Dialog:context:Wife2_FindDialogueAfter_1","speaker":null}]},{"id":"FindWife11_1","characterId":"wife_11","step":"1","lines":[{"number":1,"text":"(My stomach is rumbling, but it's mealtime and all the shops around here have really long queues...)","sourceKey":"Dialog:context:Wife11_FindDialogue1_1","speaker":"{playerName}"},{"number":2,"text":"(Only this wagashi shop doesn't have any customer. It is the first time I've seen a shop like this in Drakenberg. Let's give it a try~)","sourceKey":"Dialog:context:Wife11_FindDialogue1_2","speaker":"{playerName}"},{"number":3,"text":"A graceful woman in a kimono stands at the door of the shop. When you approach, she gives you a bright smile.","sourceKey":"Dialog:context:Wife11_FindDialogue1_3","speaker":null},{"number":4,"text":"Oh my, a guest! This little shop of ours is truly proud to be in business now that we have the honor of your visit~","sourceKey":"Dialog:context:Wife11_FindDialogue1_4","speaker":"Gentle female Oni"},{"number":5,"text":"(Wow! Such a gentle big sister, she must be the model that the “Yamato Nadeshiko” ideal is based on~) Hello, table for one, please.","sourceKey":"Dialog:context:Wife11_FindDialogue1_5","speaker":"{playerName}"},{"number":6,"text":"Thank you so much for choosing to dine here! May I show you to a table by the window?","sourceKey":"Dialog:context:Wife11_FindDialogue1_6","speaker":"Gentle female Oni"},{"number":7,"text":"Anywhere is fine, I'm mainly here for the food.","sourceKey":"Dialog:context:Wife11_FindDialogue1_7","speaker":"{playerName}"},{"number":8,"text":"Of course, please wait a moment and I'll take you to your seat.","sourceKey":"Dialog:context:Wife11_FindDialogue1_8","speaker":"Gentle female Oni"},{"number":9,"text":"Okay, thank you... Wait, what the-!?","sourceKey":"Dialog:context:Wife11_FindDialogue1_9","speaker":"{playerName}"},{"number":10,"text":"The tall proprietress picks you up, carries you toward a table by the window and places you on a chair.","sourceKey":"Dialog:context:Wife11_FindDialogue1_10","speaker":null},{"number":11,"text":"Please have a seat here and rest a moment~","sourceKey":"Dialog:context:Wife11_FindDialogue1_11","speaker":"Gentle female Oni"},{"number":12,"text":"Oh... okay... Um, thank you... (Why did she hug me?!)","sourceKey":"Dialog:context:Wife11_FindDialogue1_12","speaker":"{playerName}"},{"number":13,"text":"May I offer you something to drink? Juice, soda, or perhaps an alcoholic beverage? It's all complimentary, as long as it makes you happy~","sourceKey":"Dialog:context:Wife11_FindDialogue1_13","speaker":"Gentle female Oni"},{"number":14,"text":"Um, that’ alright, just water please... I’m actually ready to order now, I’d like to try your regular wagashi.","sourceKey":"Dialog:context:Wife11_FindDialogue1_14","speaker":"{playerName}"},{"number":15,"text":"Very well, understood. Please wait a moment while I prepare it for you.","sourceKey":"Dialog:context:Wife11_FindDialogue1_15","speaker":"Gentle female Oni"},{"number":16,"text":"Thank you. (Wow, this shop owner is really enthusiastic... not to mention strong.)","sourceKey":"Dialog:context:Wife11_FindDialogue1_16","speaker":"{playerName}"},{"number":17,"text":"You suddenly hear a loud noise from the kitchen.","sourceKey":"Dialog:context:Wife11_FindDialogue1_17","speaker":null},{"number":18,"text":"W-what was that sound? What happened?!","sourceKey":"Dialog:context:Wife11_FindDialogue1_18","speaker":"{playerName}"},{"number":19,"text":"Thank you for waiting. I'm sorry to have startled you, I was just preparing your dish... Here's your wagashi.","sourceKey":"Dialog:context:Wife11_FindDialogue1_19","speaker":"Gentle female Oni"},{"number":20,"text":"Thank you... Mmmh, this is delicious! I didn't expect to find such authentic wagashi in Drakenberg!","sourceKey":"Dialog:context:Wife11_FindDialogue1_20","speaker":"{playerName}"},{"number":21,"text":"Wonderful, it's my greatest honor to see you enjoy your meal. Please wait, if you will...","sourceKey":"Dialog:context:Wife11_FindDialogue1_21","speaker":"Gentle female Oni"},{"number":22,"text":"Soon, the Oni brings out another plate of wagashi from the kitchen.","sourceKey":"Dialog:context:Wife11_FindDialogue1_22","speaker":null},{"number":23,"text":"Hmm? I only ordered one serving though, didn't I?","sourceKey":"Dialog:context:Wife11_FindDialogue1_23","speaker":"{playerName}"},{"number":24,"text":"This is a complimentary gift to thank you for dining with us. Please enjoy!","sourceKey":"Dialog:context:Wife11_FindDialogue1_24","speaker":"Gentle female Oni"},{"number":25,"text":"Oh, okay. Thanks...","sourceKey":"Dialog:context:Wife11_FindDialogue1_25","speaker":"{playerName}"},{"number":26,"text":"After watching you finish, the Oni brings out another plate of wagashi from the kitchen.","sourceKey":"Dialog:context:Wife11_FindDialogue1_26","speaker":null},{"number":27,"text":"Over the course of the afternoon, you end up eating a total of ten servings.","sourceKey":"Dialog:context:Wife11_FindDialogue1_27","speaker":null},{"number":28,"text":"*Burp* No, please... I really... *burp* can't eat anymore... Thank you so much... *burp* for your hospitality...","sourceKey":"Dialog:context:Wife11_FindDialogue1_28","speaker":"{playerName}"},{"number":29,"text":"Are you sure you're full, my liege? Please don't hesitate to take the remaining wagashi with you as a gift to thank you for your visit~","sourceKey":"Dialog:context:Wife11_FindDialogue1_29","speaker":"Gentle female Oni"},{"number":30,"text":"I apologize for any shortcomings in my service. I hope to have the honor of a future visit~","sourceKey":"Dialog:context:Wife11_FindDialogue1_30","speaker":"Gentle female Oni"},{"number":31,"text":"You arrive at a wagashi shop.","sourceKey":"Dialog:context:Wife11_FindDialogue1_Text","speaker":null}]},{"id":"FindWife11_2","characterId":"wife_11","step":"2","lines":[{"number":1,"text":"Welcome to our shop! What would you like to eat today, my liege? I'll do my best to serve you wholeheartedly~","sourceKey":"Dialog:context:Wife11_FindDialogue2_1","speaker":"Gentle female Oni"}]},{"id":"FindWife11_3","characterId":"wife_11","step":"3","lines":[{"number":1,"text":"Why are there so many people here today? And they're all adventurers.","sourceKey":"Dialog:context:Wife11_FindDialogue3_1","speaker":"{playerName}"},{"number":2,"text":"You were about to push forward to find out what was going on when suddenly a series of loud blows came from inside the shop.","sourceKey":"Dialog:context:Wife11_FindDialogue3_2","speaker":null},{"number":3,"text":"Aaaugh! What's going on?","sourceKey":"Dialog:context:Wife11_FindDialogue3_3","speaker":"{playerName}"},{"number":4,"text":"Humph, you must be a newbie... Get out of here if you're not prepared, otherwise you might lose your life.","sourceKey":"Dialog:context:Wife11_FindDialogue3_4","speaker":"Adventurer"},{"number":5,"text":"This is the Oni Gate, it has a danger level of S!","sourceKey":"Dialog:context:Wife11_FindDialogue3_5","speaker":"Adventurer"},{"number":6,"text":"Danger level...?","sourceKey":"Dialog:context:Wife11_FindDialogue3_6","speaker":"{playerName}"},{"number":7,"text":"Haven't you heard the legend? There’s a terrifying Oni Archdemon hiding in this shop!","sourceKey":"Dialog:context:Wife11_FindDialogue3_7","speaker":"Adventurer"},{"number":8,"text":"She appears a woman with immense strength, but she’s extremely violent! No adventurer has ever dared to go toe to toe with her...","sourceKey":"Dialog:context:Wife11_FindDialogue3_8","speaker":"Adventurer"},{"number":9,"text":"Every year at around this time, she uses a weapon weighing thousands of pounds to smash the bones of her captives and turn them into ingredients for cooking...","sourceKey":"Dialog:context:Wife11_FindDialogue3_9","speaker":"Adventurer"},{"number":10,"text":"*Bang! Bang! Bang!*","sourceKey":"Dialog:context:Wife11_FindDialogue3_10","speaker":"A mysterious voice"},{"number":11,"text":"— There it is! That’s the sound!","sourceKey":"Dialog:context:Wife11_FindDialogue3_11","speaker":"Adventurer"},{"number":12,"text":"Umm... (Are they talking about the boss of the shop? That sounds a little exaggerated, she can't really be all that bad...)","sourceKey":"Dialog:context:Wife11_FindDialogue3_12","speaker":"{playerName}"},{"number":13,"text":"We’re finally here, and now we’re ready! We’ll take down that Oni Archdemon for sure!","sourceKey":"Dialog:context:Wife11_FindDialogue3_13","speaker":"Adventurer"},{"number":14,"text":"The adventurers in front of the shop let out a rousing cheer. At that moment, a tall figure steps out of the wagashi shop...","sourceKey":"Dialog:context:Wife11_FindDialogue3_14","speaker":null},{"number":15,"text":"It’s the tall, very strong Oni shopkeeper, and she’s holding a huge wooden hammer. The hammer, her clothes and her face are all stained with a bright red liquid.","sourceKey":"Dialog:context:Wife11_FindDialogue3_15","speaker":null},{"number":16,"text":"She looks around at the silent adventurers and breaks out in a wide, gentle smile.","sourceKey":"Dialog:context:Wife11_FindDialogue3_16","speaker":null},{"number":17,"text":"Oh my, so many guests. Please come inside, my lords and ladies~","sourceKey":"Dialog:context:Wife11_FindDialogue3_17","speaker":"Gentle female Oni"},{"number":18,"text":"For a second, no one dared to make a sound. Then all the adventurers erupt in a loud cry:","sourceKey":"Dialog:context:Wife11_FindDialogue3_18","speaker":null},{"number":19,"text":"Run away! Run away, run away!!!","sourceKey":"Dialog:context:Wife11_FindDialogue3_19","speaker":"Adventurer"},{"number":20,"text":"In a puff of smoke, the adventurers scatter with their tails between their legs. The area in front of the wagashi shop is deserted once more.","sourceKey":"Dialog:context:Wife11_FindDialogue3_20","speaker":null},{"number":21,"text":"Why did all the nice guests run away again...? I stayed up all night making mochi hoping to share them with everyone... Oh, hello there, esteemed mushroom lord~ You're still here?","sourceKey":"Dialog:context:Wife11_FindDialogue3_21","speaker":"Gentle female Oni"},{"number":22,"text":"Yeah... So just now you were... pounding mochi?","sourceKey":"Dialog:context:Wife11_FindDialogue3_22","speaker":"{playerName}"},{"number":23,"text":"That’s right~ Our shop has a new signature product— strawberry-filled mochi!","sourceKey":"Dialog:context:Wife11_FindDialogue3_23","speaker":"Gentle female Oni"},{"number":24,"text":"I used a little too much force again, though, and got strawberry filling all over myself. I'm so sorry you had to see my clumsy side...","sourceKey":"Dialog:context:Wife11_FindDialogue3_24","speaker":"Gentle female Oni"},{"number":25,"text":"Strawberry mochi... (So that’s where those rumors came from. Though I admit, she does look a bit scary...)","sourceKey":"Dialog:context:Wife11_FindDialogue3_25","speaker":"{playerName}"},{"number":26,"text":"Crowds of guests often show up at my door, but for some reason they always end up leaving. Now these fresh strawberry mochi will all spoil again...","sourceKey":"Dialog:context:Wife11_FindDialogue3_26","speaker":"Gentle female Oni"},{"number":27,"text":"Well then, let me try them. It sounds delicious~","sourceKey":"Dialog:context:Wife11_FindDialogue3_27","speaker":"{playerName}"},{"number":28,"text":"Really? Are you really willing to try them? Thank you so much, you're the only customer who hasn't left after all this time!","sourceKey":"Dialog:context:Wife11_FindDialogue3_28","speaker":"Gentle female Oni"},{"number":29,"text":"My name is Ookami. May I ask what your name is, my liege? I’d like to provide the best service possible for you!","sourceKey":"Dialog:context:Wife11_FindDialogue3_29","speaker":"Ookami"},{"number":30,"text":"Just call me {playerName}, you don’t have to keep calling me “my liege.”","sourceKey":"Dialog:context:Wife11_FindDialogue3_30","speaker":"{playerName}"},{"number":31,"text":"{playerName}... I understand! From now on, {playerName} will be my most important guest~","sourceKey":"Dialog:context:Wife11_FindDialogue3_31","speaker":"Ookami"},{"number":32,"text":"Please, come in~ Our daily batch of strawberry mochi are all for {playerName}~","sourceKey":"Dialog:context:Wife11_FindDialogue3_32","speaker":"Ookami"},{"number":33,"text":"No, really! That’s too much! Way too much!","sourceKey":"Dialog:context:Wife11_FindDialogue3_33","speaker":"{playerName}"},{"number":34,"text":"A large group of adventurers gather in front of the wagashi shop.","sourceKey":"Dialog:context:Wife11_FindDialogue3_Text","speaker":null}]},{"id":"FindWife11_4","characterId":"wife_11","step":"4","lines":[{"number":1,"text":"Your Excellency {playerName}! So you've come to my little shop again~ Please come in and have a seat, I'll take good care of you~","sourceKey":"Dialog:context:Wife11_FindDialogue4_1","speaker":"Ookami"}]},{"id":"FindWife11_5","characterId":"wife_11","step":"5","lines":[{"number":1,"text":"Ookami comes toward your table carrying a stack of goods taller than herself.","sourceKey":"Dialog:context:Wife11_FindDialogue5_1","speaker":null},{"number":2,"text":"Oh my, we’re always glad to see {playerName}, but unfortunately we're not open today...","sourceKey":"Dialog:context:Wife11_FindDialogue5_2","speaker":"Ookami"},{"number":3,"text":"That's okay. Here, let me help you move some of those things.","sourceKey":"Dialog:context:Wife11_FindDialogue5_3","speaker":"{playerName}"},{"number":4,"text":"Before Ookami could open her mouth, you took a few of the packages she's holding. Howver, the unexpected weight of them made you fall over.","sourceKey":"Dialog:context:Wife11_FindDialogue5_4","speaker":null},{"number":5,"text":"My liege! Are you okay?","sourceKey":"Dialog:context:Wife11_FindDialogue5_5","speaker":"Ookami"},{"number":6,"text":"It's okay, I didn’t expect it to be so heavy... What are you moving, exactly? What’s in these packages?","sourceKey":"Dialog:context:Wife11_FindDialogue5_6","speaker":"{playerName}"},{"number":7,"text":"I'll take care of everything myself, there’s no need for you to worry about it~","sourceKey":"Dialog:context:Wife11_FindDialogue5_7","speaker":"Ookami"},{"number":8,"text":"But since you’re here, {playerName}, would you be willing to fulfill a small request of mine?","sourceKey":"Dialog:context:Wife11_FindDialogue5_8","speaker":"Ookami"},{"number":9,"text":"It might sound a little strange, but... would you be willing to go for a quick walk through the city with me?","sourceKey":"Dialog:context:Wife11_FindDialogue5_9","speaker":"Ookami"},{"number":10,"text":"I've always lived in Drakenberg as a shopkeeper and I really want to see more of the daily life here. But everyone seems to be afraid of me when I'm alone...","sourceKey":"Dialog:context:Wife11_FindDialogue5_10","speaker":"Ookami"},{"number":11,"text":"Sure, no problem~ Let's go on a walk, I'll go wherever you want to go!","sourceKey":"Dialog:context:Wife11_FindDialogue5_11","speaker":"{playerName}"},{"number":12,"text":"Really? Thank you so much, {playerName}! You’re very kind~","sourceKey":"Dialog:context:Wife11_FindDialogue5_12","speaker":"Ookami"},{"number":13,"text":"You wander around the market with Ookami for a long time.","sourceKey":"Dialog:context:Wife11_FindDialogue5_13","speaker":null},{"number":14,"text":"Phew~ We've been to nearly every stall by now. My stomach begins growling now. You must be hungry too, right? Let's go get some food.","sourceKey":"Dialog:context:Wife11_FindDialogue5_14","speaker":"{playerName}"},{"number":15,"text":"Ookami took out a beautifully packaged bento box.","sourceKey":"Dialog:context:Wife11_FindDialogue5_15","speaker":null},{"number":16,"text":"This is a little something I prepared specially for {playerName}, as a thank you for all the kindness you’ve shown me... I hope you like it.","sourceKey":"Dialog:context:Wife11_FindDialogue5_16","speaker":"Ookami"},{"number":17,"text":"Whoooa, there’s so much food in here! Thank you, it all looks delicious~ Let's find somewhere to sit down, we can eat it together.","sourceKey":"Dialog:context:Wife11_FindDialogue5_17","speaker":"{playerName}"},{"number":18,"text":"Try this— here, open your mouth~","sourceKey":"Dialog:context:Wife11_FindDialogue5_18","speaker":"Ookami"},{"number":19,"text":"Huh!? Oh, *mmph*... (I feel a little shy... but it's so delicious!)","sourceKey":"Dialog:context:Wife11_FindDialogue5_19","speaker":"{playerName}"},{"number":20,"text":"Thank you for your company. Today has been one of the happiest days I’ve had since coming to Drakenberg. But days like this are coming to an end... My shop will close from today.","sourceKey":"Dialog:context:Wife11_FindDialogue5_20","speaker":"Ookami"},{"number":21,"text":"Closing? But why...? Your wagashi is amazing.","sourceKey":"Dialog:context:Wife11_FindDialogue5_21","speaker":"{playerName}"},{"number":22,"text":"Business has always been bad, to be honest. Moving those packages before was actually preparation for closing down... It's my poor management that led to this.","sourceKey":"Dialog:context:Wife11_FindDialogue5_22","speaker":"Ookami"},{"number":23,"text":"I know that everyone is afraid of my strength, I can tell, but it's the nature of the Oni clan. In our clans, power determines everything.","sourceKey":"Dialog:context:Wife11_FindDialogue5_23","speaker":"Ookami"},{"number":24,"text":"I didn't want to live like that anymore, so I came to Drakenberg from across the sea. It seems that I can't adapt to life here though, so maybe I should return home.","sourceKey":"Dialog:context:Wife11_FindDialogue5_24","speaker":"Ookami"},{"number":25,"text":"Is there no chance that things will turn for the better? If there's anything I can do to help, just let me know.","sourceKey":"Dialog:context:Wife11_FindDialogue5_25","speaker":"{playerName}"},{"number":26,"text":"You’ve always been incredibly gentle and friendly to people. There might be a cultural barrier here, but it's definitely not your fault.","sourceKey":"Dialog:context:Wife11_FindDialogue5_26","speaker":"{playerName}"},{"number":27,"text":"If I had met you earlier, maybe things really could have changed~","sourceKey":"Dialog:context:Wife11_FindDialogue5_27","speaker":"Ookami"},{"number":28,"text":"The ship bound for Touno Island will set sail soon... Will you come to see me off?","sourceKey":"Dialog:context:Wife11_FindDialogue5_28","speaker":"Ookami"},{"number":29,"text":"Sure. And if you have a change of heart, please let me know.","sourceKey":"Dialog:context:Wife11_FindDialogue5_29","speaker":"{playerName}"},{"number":30,"text":"Thank you very much, I will keep that in mind.","sourceKey":"Dialog:context:Wife11_FindDialogue5_30","speaker":"Ookami"},{"number":31,"text":"The area in front of the wagashi shop is piled up with all kinds of goods.","sourceKey":"Dialog:context:Wife11_FindDialogue5_Text","speaker":null}]},{"id":"FindWife11_After","characterId":"wife_11","step":"After","lines":[{"number":1,"text":"Pick out some of your favorite ingredients. I'll prepare for your dinner tonight~","sourceKey":"Dialog:context:Wife11_FindDialogueAfter_1","speaker":"Ookami"}]},{"id":"FindWife14_1","characterId":"wife_14","step":"1","lines":[{"number":1,"text":"*Crying...* I'm really sorry!","sourceKey":"Dialog:context:Wife14_FindDialogue1_1","speaker":"Rash female handler"},{"number":2,"text":"You're just wasting my time! I even gathered a powerful team together for this!","sourceKey":"Dialog:context:Wife14_FindDialogue1_2","speaker":"Elite adventurer"},{"number":3,"text":"(Wait a second... That outfit belongs to someone from the guild, why are they arguing with an adventurer here?)","sourceKey":"Dialog:context:Wife14_FindDialogue1_3","speaker":"{playerName}"},{"number":4,"text":"Hey you, walking mushroom, can you help me out? I finally got the S-rank commission I've been waiting for, I've been prepping for this for a really long time now.","sourceKey":"Dialog:context:Wife14_FindDialogue1_4","speaker":"Elite adventurer"},{"number":5,"text":"But then when I went to the guild to receive the mission details today the staff assigned me a completely different task from what we agreed on!","sourceKey":"Dialog:context:Wife14_FindDialogue1_5","speaker":"Elite adventurer"},{"number":6,"text":"The mission is just to find a lost cat! It's the lowest D-rank commission there is!","sourceKey":"Dialog:context:Wife14_FindDialogue1_6","speaker":"Elite adventurer"},{"number":7,"text":"Really? That’s a pretty serious mistake...","sourceKey":"Dialog:context:Wife14_FindDialogue1_7","speaker":"{playerName}"},{"number":8,"text":"It’s-it's all my fault... I mixed up the commission orders, this one was originally meant for someone else...","sourceKey":"Dialog:context:Wife14_FindDialogue1_8","speaker":"Rash female handler"},{"number":9,"text":"I’ll find a way to handle this D-rank commission for you and restore your certificate for undertaking S-rank commission too!","sourceKey":"Dialog:context:Wife14_FindDialogue1_9","speaker":"Rash female handler"},{"number":10,"text":"That’s better, I'll leave it to you then.","sourceKey":"Dialog:context:Wife14_FindDialogue1_10","speaker":"Elite adventurer"},{"number":11,"text":"The elite adventurers and their fellows left.","sourceKey":"Dialog:context:Wife14_FindDialogue1_11","speaker":null},{"number":12,"text":"... What a disaster! I messed up again!","sourceKey":"Dialog:context:Wife14_FindDialogue1_12","speaker":"Rash female handler"},{"number":13,"text":"Don't panic, maybe I can help too.","sourceKey":"Dialog:context:Wife14_FindDialogue1_13","speaker":"{playerName}"},{"number":14,"text":"... Ah, really? Thanks, that’s so nice of you~ My name is Sofia, what's yours?","sourceKey":"Dialog:context:Wife14_FindDialogue1_14","speaker":"Sofia"},{"number":15,"text":"My name is {playerName}... Why did such a basic mistake like this happen? Do you really work at the guild?","sourceKey":"Dialog:context:Wife14_FindDialogue1_15","speaker":"{playerName}"},{"number":16,"text":"Of course I do! I'm the official guild handler... though I’m still undergoing training at the moment.","sourceKey":"Dialog:context:Wife14_FindDialogue1_16","speaker":"Sofia"},{"number":17,"text":"The two people who requested those commissions should come see me at the same time! I just got confused for a moment is all...","sourceKey":"Dialog:context:Wife14_FindDialogue1_17","speaker":"Sofia"},{"number":18,"text":"So you're a newbie... Let me see the commission scroll for that D-rank task, maybe there's a clue.","sourceKey":"Dialog:context:Wife14_FindDialogue1_18","speaker":"{playerName}"},{"number":19,"text":"After carefully studying the commission scroll, you find what you need to know. By following the clues of the case, you quickly find the lost cat.","sourceKey":"Dialog:context:Wife14_FindDialogue1_19","speaker":null},{"number":20,"text":"Wow, you're amazing! You found it so fast!","sourceKey":"Dialog:context:Wife14_FindDialogue1_20","speaker":"Sofia"},{"number":21,"text":"This will be really easy to explain it to that adventurer~ All the troubles are finally solved! Yay!","sourceKey":"Dialog:context:Wife14_FindDialogue1_21","speaker":"Sofia"},{"number":22,"text":"(Really...? Even though that simple commission is done I still feel like something has been overlooked...)","sourceKey":"Dialog:context:Wife14_FindDialogue1_22","speaker":"{playerName}"},{"number":23,"text":"Sofia, has everything really been taken care of...? According to you, you confused a D-rank commission with an S-rank commission, right?","sourceKey":"Dialog:context:Wife14_FindDialogue1_23","speaker":"{playerName}"},{"number":24,"text":"Yeah, that's why that elite adventurer was so angry. His abilities are S-class, after all.","sourceKey":"Dialog:context:Wife14_FindDialogue1_24","speaker":"Sofia"},{"number":25,"text":"Does that mean there's a noob with only D-rank power doing an S-rank commission right now...?","sourceKey":"Dialog:context:Wife14_FindDialogue1_25","speaker":"{playerName}"},{"number":26,"text":"... Uh-oh.","sourceKey":"Dialog:context:Wife14_FindDialogue1_26","speaker":"Sofia"},{"number":27,"text":"......","sourceKey":"Dialog:context:Wife14_FindDialogue1_27","speaker":"{playerName}"},{"number":28,"text":"... I’ll report to the guild first! Then I'll go and find the nearest priest!","sourceKey":"Dialog:context:Wife14_FindDialogue1_28","speaker":"Sofia"},{"number":29,"text":"It sounds like something is going on in front of the fortune-telling shop.","sourceKey":"Dialog:context:Wife14_FindDialogue1_Text","speaker":null}]},{"id":"FindWife14_2","characterId":"wife_14","step":"2","lines":[{"number":1,"text":"Ah, hello! Thanks to you, everything turned out all right last time... That new adventurer is also okay, we found her just in time. Aheheheh...","sourceKey":"Dialog:context:Wife14_FindDialogue2_1","speaker":"Sofia"}]},{"id":"FindWife14_3","characterId":"wife_14","step":"3","lines":[{"number":1,"text":"The fortune teller said my work will go smoothly! I promise I'll work hard!","sourceKey":"Dialog:context:Wife14_FindDialogue3_1","speaker":"Sofia"}]},{"id":"FindWife14_4","characterId":"wife_14","step":"4","lines":[{"number":1,"text":"Wow, you came! Are you here to take on a quest? You seem super powerful, how about taking on an S-rank commission right from the start!","sourceKey":"Dialog:context:Wife14_FindDialogue4_1","speaker":"Sofia"},{"number":2,"text":"I'm just passing by so I'll have to pass on taking a commission. I'm not actually a full-time adventurer.","sourceKey":"Dialog:context:Wife14_FindDialogue4_2","speaker":"{playerName}"},{"number":3,"text":"Shouldn't commissions be distributed in the guild? Why are you here?","sourceKey":"Dialog:context:Wife14_FindDialogue4_3","speaker":"{playerName}"},{"number":4,"text":"I'm still in my probationary period, so I need to do some subcontracting work in a designated district first.","sourceKey":"Dialog:context:Wife14_FindDialogue4_4","speaker":"Sofia"},{"number":5,"text":"But I’m doing my best! After I become a regular employee, I can work as a formal handler in the guild!","sourceKey":"Dialog:context:Wife14_FindDialogue4_5","speaker":"Sofia"},{"number":6,"text":"So motivated~ (I don't really understand the guild's regulations, so I'll observe the work of this trainee employee.)","sourceKey":"Dialog:context:Wife14_FindDialogue4_6","speaker":"{playerName}"},{"number":7,"text":"Sofia is carefully organizing the commission papers when a merchant comes to her booth.","sourceKey":"Dialog:context:Wife14_FindDialogue4_7","speaker":null},{"number":8,"text":"Miss, I have a very important shipment to deliver to the northern border. No mistakes allowed! Please help me post an S-rank commission!","sourceKey":"Dialog:context:Wife14_FindDialogue4_8","speaker":"Merchant"},{"number":9,"text":"Here's the shipping manifest and the commission fee. Help me find the most reliable adventurer, and money is not a problem!","sourceKey":"Dialog:context:Wife14_FindDialogue4_9","speaker":"Merchant"},{"number":10,"text":"Okay, leave it to me! Let me see your list of goods...","sourceKey":"Dialog:context:Wife14_FindDialogue4_10","speaker":"Sofia"},{"number":11,"text":"Ah…? Such few?","sourceKey":"Dialog:context:Wife14_FindDialogue4_11","speaker":"Sofia"},{"number":12,"text":"What do you mean by that?! These goods mean the world to me. Nothing can go wrong!","sourceKey":"Dialog:context:Wife14_FindDialogue4_12","speaker":"Merchant"},{"number":13,"text":"But such few goods are not worth an S-rank commission. It's a waste of money. Whoever takes this commission will definitely see you as a sucker...","sourceKey":"Dialog:context:Wife14_FindDialogue4_13","speaker":"Sofia"},{"number":14,"text":"What did you say!? How dare you look down on me!?","sourceKey":"Dialog:context:Wife14_FindDialogue4_14","speaker":"Merchant"},{"number":15,"text":"Aaaugh!! Why... why are you angry? Did I say something wrong...?","sourceKey":"Dialog:context:Wife14_FindDialogue4_15","speaker":"Sofia"},{"number":16,"text":"(I know what she means, but she really didn’t know how to express it. If this continues, she'll only make it worse!)","sourceKey":"Dialog:context:Wife14_FindDialogue4_16","speaker":"{playerName}"},{"number":17,"text":"You rush over and cover Sofia's mouth.","sourceKey":"Dialog:context:Wife14_FindDialogue4_17","speaker":null},{"number":18,"text":"Oomph—! Uughhhh—!","sourceKey":"Dialog:context:Wife14_FindDialogue4_18","speaker":"Sofia"},{"number":19,"text":"Excuse me, sir! Please don't be angry. She doesn’t look down on you at all!","sourceKey":"Dialog:context:Wife14_FindDialogue4_19","speaker":"{playerName}"},{"number":20,"text":"It's just that based on their evaluation, many good adventurers will take your commission even without such generous rewards.","sourceKey":"Dialog:context:Wife14_FindDialogue4_20","speaker":"{playerName}"},{"number":21,"text":"S-rank missions require recruiting elite adventurers, which will take much more time and may delay your arrangements.","sourceKey":"Dialog:context:Wife14_FindDialogue4_21","speaker":"{playerName}"},{"number":22,"text":"We will take all of your concerns into account and arrange for a more suitable mission rating. Would that be okay?","sourceKey":"Dialog:context:Wife14_FindDialogue4_22","speaker":"{playerName}"},{"number":23,"text":"Oh, so that's what you mean... I didn't think the guild would consider my interests. I have misunderstood you. I'll leave it to you then.","sourceKey":"Dialog:context:Wife14_FindDialogue4_23","speaker":"Merchant"},{"number":24,"text":"The merchant leaves, totally satisfied. You breathe a sigh of relief and let go of Sofia.","sourceKey":"Dialog:context:Wife14_FindDialogue4_24","speaker":null},{"number":25,"text":"That was close, I'm saved... Thank you for helping me again!","sourceKey":"Dialog:context:Wife14_FindDialogue4_25","speaker":"Sofia"},{"number":26,"text":"You should really think twice before you speak, y’know. You meant well, but that almost went really badly.","sourceKey":"Dialog:context:Wife14_FindDialogue4_26","speaker":"{playerName}"},{"number":27,"text":"I'm really sorry! I'll be careful next time! I won't mess up again!","sourceKey":"Dialog:context:Wife14_FindDialogue4_27","speaker":"Sofia"},{"number":28,"text":"Just now, a confident adventurer comes in looking for vacant commissions.","sourceKey":"Dialog:context:Wife14_FindDialogue4_28","speaker":null},{"number":29,"text":"Hello! Are there any A-rank commissions available? I’ll take whatever you’ve got. Here’s my ID card.","sourceKey":"Dialog:context:Wife14_FindDialogue4_29","speaker":"Adventurer"},{"number":30,"text":"Got it! Let’s see... Whoa, seriously?! You're way too weak for A-rank commissions. You’d die in a heartbeat! Start from something lower level for now.","sourceKey":"Dialog:context:Wife14_FindDialogue4_30","speaker":"Sofia"},{"number":31,"text":"Hey—!!!","sourceKey":"Dialog:context:Wife14_FindDialogue4_31","speaker":"{playerName}"},{"number":32,"text":"Hey—!!!","sourceKey":"Dialog:context:Wife14_FindDialogue4_32","speaker":"{playerName}"},{"number":33,"text":"Sofia is working in front of the divination shop.","sourceKey":"Dialog:context:Wife14_FindDialogue4_Text","speaker":null}]},{"id":"FindWife14_5","characterId":"wife_14","step":"5","lines":[{"number":1,"text":"Heheh~ I've learned a lot recently! I’ll be a professional handler in no time~","sourceKey":"Dialog:context:Wife14_FindDialogue5_1","speaker":"Sofia"}]},{"id":"FindWife14_6","characterId":"wife_14","step":"6","lines":[{"number":1,"text":"Welcome~ Are you here to take on a commission, or to post one? Please fill out this form... How was that? It was perfect, wasn’t it?","sourceKey":"Dialog:context:Wife14_FindDialogue6_1","speaker":"Sofia"}]},{"id":"FindWife14_7","characterId":"wife_14","step":"7","lines":[{"number":1,"text":"{playerName}! I'm on my break right now, let's go grab something to eat together~","sourceKey":"Dialog:context:Wife14_FindDialogue7_1","speaker":"Sofia"}]},{"id":"FindWife14_8","characterId":"wife_14","step":"8","lines":[{"number":1,"text":"{playerName}... What should I do...","sourceKey":"Dialog:context:Wife14_FindDialogue8_1","speaker":"Sofia"},{"number":2,"text":"I’m going to take the evaluation for full-time employment soon... As long as I can collect enough satisfactory reviews from clients and adventurers I’ll be hired as a full-time employee.","sourceKey":"Dialog:context:Wife14_FindDialogue8_2","speaker":"Sofia"},{"number":3,"text":"That's a good thing, isn't it? Haven’t you been looking forward to getting hired full-time?","sourceKey":"Dialog:context:Wife14_FindDialogue8_3","speaker":"{playerName}"},{"number":4,"text":"But... but what should I do...? Aaaaaugh!!!","sourceKey":"Dialog:context:Wife14_FindDialogue8_4","speaker":"Sofia"},{"number":5,"text":"Sofia suddenly hugs you and bursts into tears.","sourceKey":"Dialog:context:Wife14_FindDialogue8_5","speaker":null},{"number":6,"text":"I’ve caused so much trouble... and I can't even speak properly... No one is ever satisfied with me!","sourceKey":"Dialog:context:Wife14_FindDialogue8_6","speaker":"Sofia"},{"number":7,"text":"I... I'm going to be fired for sure!","sourceKey":"Dialog:context:Wife14_FindDialogue8_7","speaker":"Sofia"},{"number":8,"text":"(This girl is usually so confident, I didn't expect her to be so scared.)","sourceKey":"Dialog:context:Wife14_FindDialogue8_8","speaker":"{playerName}"},{"number":9,"text":"... Sofia, don't be afraid, cheer up.","sourceKey":"Dialog:context:Wife14_FindDialogue8_9","speaker":"{playerName}"},{"number":10,"text":"Although you’ve probably caused your fair share of trouble, your enthusiasm and discipline in your work are undeniable.","sourceKey":"Dialog:context:Wife14_FindDialogue8_10","speaker":"{playerName}"},{"number":11,"text":"As a guild member, what really matters is to serve others wholeheartedly. You're definitely qualified from this perspective.","sourceKey":"Dialog:context:Wife14_FindDialogue8_11","speaker":"{playerName}"},{"number":12,"text":"*Crying* Th-thank you... {playerName}, can you accompany me to collect the surveys? I... I'm too nervous to do it alone...","sourceKey":"Dialog:context:Wife14_FindDialogue8_12","speaker":"Sofia"},{"number":13,"text":"Ok. No matter what the outcome is, I’ll be right here with you.","sourceKey":"Dialog:context:Wife14_FindDialogue8_13","speaker":"{playerName}"},{"number":14,"text":"At that moment, a familiar figure comes to her desk.","sourceKey":"Dialog:context:Wife14_FindDialogue8_14","speaker":null},{"number":15,"text":"Oh, is it time for your evaluation already? Time flies, I didn't expect you to reach this point.","sourceKey":"Dialog:context:Wife14_FindDialogue8_15","speaker":"Elite adventurer"},{"number":16,"text":"Yikes, it's you—! I'm really sorry for mixing up the commission forms before...","sourceKey":"Dialog:context:Wife14_FindDialogue8_16","speaker":"Sofia"},{"number":17,"text":"Sofia meant to keep apologizing but the adventurer had already left his review on the evaluation form.","sourceKey":"Dialog:context:Wife14_FindDialogue8_17","speaker":null},{"number":18,"text":"*Crying*... Wait, really? It says “Satisfied”... Do you really think I should be hired?","sourceKey":"Dialog:context:Wife14_FindDialogue8_18","speaker":"Sofia"},{"number":19,"text":"Everyone makes mistakes, so what? When I first became an adventurer, I also took on missions that I couldn't complete and caused a lot of trouble for the guild.","sourceKey":"Dialog:context:Wife14_FindDialogue8_19","speaker":"Elite adventurer"},{"number":20,"text":"You worked hard to solve your mistake, that's enough. Keep it up, I look forward to receiving more commissions from you in the guild.","sourceKey":"Dialog:context:Wife14_FindDialogue8_20","speaker":"Elite adventurer"},{"number":21,"text":"——!!! Thank you! Thank you so much!","sourceKey":"Dialog:context:Wife14_FindDialogue8_21","speaker":"Sofia"},{"number":22,"text":"After the elite adventurer left, the merchant who had previously posted a commission with Sofia came to her desk.","sourceKey":"Dialog:context:Wife14_FindDialogue8_22","speaker":null},{"number":23,"text":"Good work, girl! Thanks to your suggestion, I saved a lot of money. You should still be careful with your words, of course, but keep up the good work!","sourceKey":"Dialog:context:Wife14_FindDialogue8_23","speaker":"Merchant"},{"number":24,"text":"The merchant also checked the “Satisfied\" box.","sourceKey":"Dialog:context:Wife14_FindDialogue8_24","speaker":null},{"number":25,"text":"One by one, the people Sofia had received came to rate her, although every one of them gave had a different suggestion for her.","sourceKey":"Dialog:context:Wife14_FindDialogue8_25","speaker":null},{"number":26,"text":"Even so, they all left a “Satisfied\" evaluation and gave her a hearty “Keep it up!\"","sourceKey":"Dialog:context:Wife14_FindDialogue8_26","speaker":null},{"number":27,"text":"The official result soon came out: The intern Sofia passed her probation review and became an official guild handler.","sourceKey":"Dialog:context:Wife14_FindDialogue8_27","speaker":null},{"number":28,"text":"*Sobbing*... Thank you, everyone! I actually passed...! You were all so good to me!","sourceKey":"Dialog:context:Wife14_FindDialogue8_28","speaker":"Sofia"},{"number":29,"text":"All of this is thanks to your own efforts. Everyone can see how hard you work every day, which why they all showed up to support you.","sourceKey":"Dialog:context:Wife14_FindDialogue8_29","speaker":"{playerName}"},{"number":30,"text":"{playerName}! Thank you so much! If it weren't for you by my side, I would have made so many mistakes...","sourceKey":"Dialog:context:Wife14_FindDialogue8_30","speaker":"Sofia"},{"number":31,"text":"Without you, I really don't know what to do...","sourceKey":"Dialog:context:Wife14_FindDialogue8_31","speaker":"Sofia"},{"number":32,"text":"Then just keep working hard, I look forward to seeing a more mature, more capable Sofia.","sourceKey":"Dialog:context:Wife14_FindDialogue8_32","speaker":"{playerName}"},{"number":33,"text":"... I will! For {playerName}, for everyone, and for myself!","sourceKey":"Dialog:context:Wife14_FindDialogue8_33","speaker":"Sofia"},{"number":34,"text":"Sofia site behind her desk, shaking with joyful tears.","sourceKey":"Dialog:context:Wife14_FindDialogue8_Text","speaker":null}]},{"id":"FindWife14_After","characterId":"wife_14","step":"After","lines":[{"number":1,"text":"Ah! This place is so nostalgic~ {playerName}. Do you still remember that time...","sourceKey":"Dialog:context:Wife14_FindDialogueAfter_1","speaker":"Sofia"}]},{"id":"FindWife15_1","characterId":"wife_15","step":"1","lines":[{"number":1,"text":"......","sourceKey":"Dialog:context:Wife15_FindDialogue1_1","speaker":"Weird female student"},{"number":2,"text":"(Hmm? That outfit... is she a student?)","sourceKey":"Dialog:context:Wife15_FindDialogue1_2","speaker":"{playerName}"},{"number":3,"text":"The girl notices you too. Just as you were about to approach her, she suddenly starts speaking strange words and gesticulating exaggeratedly.","sourceKey":"Dialog:context:Wife15_FindDialogue1_3","speaker":null},{"number":4,"text":"...... Quwota farilwa?","sourceKey":"Dialog:context:Wife15_FindDialogue1_4","speaker":"Weird female student"},{"number":5,"text":"(Ah!? What language is this!?)","sourceKey":"Dialog:context:Wife15_FindDialogue1_5","speaker":"{playerName}"},{"number":6,"text":"You try to respond with gestures, but she keeps speaking in a language you don’t recognize.","sourceKey":"Dialog:context:Wife15_FindDialogue1_6","speaker":null},{"number":7,"text":"You listen with total concentration for a couple minutes before finally realizing that you still couldn't understand her.","sourceKey":"Dialog:context:Wife15_FindDialogue1_7","speaker":null},{"number":8,"text":"... Augh! We can't communicate at all!","sourceKey":"Dialog:context:Wife15_FindDialogue1_8","speaker":"{playerName}"},{"number":9,"text":"Oh, so you can speak...","sourceKey":"Dialog:context:Wife15_FindDialogue1_9","speaker":"Weird female student"},{"number":10,"text":"Of course! Just ask first when you meet someone new!","sourceKey":"Dialog:context:Wife15_FindDialogue1_10","speaker":"{playerName}"},{"number":11,"text":"After a perfectly normal conversation, you learn that her name is Chihaya Shiina, and that she is a student.","sourceKey":"Dialog:context:Wife15_FindDialogue1_11","speaker":null},{"number":12,"text":"...... That was the language of the walking mushrooms, I learned it in a textbook. It took me a long time to master, but I still need practice.","sourceKey":"Dialog:context:Wife15_FindDialogue1_12","speaker":"Chihaya"},{"number":13,"text":"Regardless of the result just now, I suppose this was also an answer. Thank you for your help... Quwota farilwa.","sourceKey":"Dialog:context:Wife15_FindDialogue1_13","speaker":"Chihaya"},{"number":14,"text":"Speak normally!","sourceKey":"Dialog:context:Wife15_FindDialogue1_14","speaker":"{playerName}"},{"number":15,"text":"You see a girl is standing at the entrance of the dungeon garden.","sourceKey":"Dialog:context:Wife15_FindDialogue1_Text","speaker":null}]},{"id":"FindWife15_2","characterId":"wife_15","step":"2","lines":[{"number":1,"text":"You came from a faraway land, didn’t you? That's wonderful, travel expenses to Drakenberg are far from cheap. When my scholarship comes through, I’m hoping to travel to other places too.","sourceKey":"Dialog:context:Wife15_FindDialogue2_1","speaker":"Chihaya"}]},{"id":"FindWife15_3","characterId":"wife_15","step":"3","lines":[{"number":1,"text":"There is a lot of free time to do in the academy. The other students always work in groups, but I prefer to do my research alone.","sourceKey":"Dialog:context:Wife15_FindDialogue3_1","speaker":"Chihaya"}]},{"id":"FindWife15_4","characterId":"wife_15","step":"4","lines":[{"number":1,"text":"Miss Shiina... what are you doing...?","sourceKey":"Dialog:context:Wife15_FindDialogue4_1","speaker":"{playerName}"},{"number":2,"text":"Oh, it’s you. As you can see, I'm completing a project researching the attack range of the magic wolves.","sourceKey":"Dialog:context:Wife15_FindDialogue4_2","speaker":"Chihaya"},{"number":3,"text":"The pack of magic wolves are baring their fangs and moving restlessly around Chihaya, but she remains totally unmoved.","sourceKey":"Dialog:context:Wife15_FindDialogue4_3","speaker":null},{"number":4,"text":"Hmm... This distance still isn’t enough to trigger an attack, I need to get closer...","sourceKey":"Dialog:context:Wife15_FindDialogue4_4","speaker":"Chihaya"},{"number":5,"text":"Don't do that! These wolves are super dangerous!","sourceKey":"Dialog:context:Wife15_FindDialogue4_5","speaker":"{playerName}"},{"number":6,"text":"Before the wolf pack was provoked to attack, you grab Chihaya and flee to safety.","sourceKey":"Dialog:context:Wife15_FindDialogue4_6","speaker":null},{"number":7,"text":"Chihaya finally seemed to feel frightened too, she kept holding her chest and gasping for breath.","sourceKey":"Dialog:context:Wife15_FindDialogue4_7","speaker":null},{"number":8,"text":"*Huff, huff*... Don't pull dangerous stunts like that anymore...","sourceKey":"Dialog:context:Wife15_FindDialogue4_8","speaker":"{playerName}"},{"number":9,"text":"... This is... wonderful...","sourceKey":"Dialog:context:Wife15_FindDialogue4_9","speaker":"Chihaya"},{"number":10,"text":"... What is?","sourceKey":"Dialog:context:Wife15_FindDialogue4_10","speaker":"{playerName}"},{"number":11,"text":"I finally obtained some perfectly accurate results, without even a centimeter of error in the data.","sourceKey":"Dialog:context:Wife15_FindDialogue4_11","speaker":"Chihaya"},{"number":12,"text":"Thank you so much. If it weren't for you saving me at the perfect time, I wouldn't have been able to record the distance with such precision.","sourceKey":"Dialog:context:Wife15_FindDialogue4_12","speaker":"Chihaya"},{"number":13,"text":"In future research I shall rely on you as well.","sourceKey":"Dialog:context:Wife15_FindDialogue4_13","speaker":"Chihaya"},{"number":14,"text":"“Future research?!” I said don't do stuff like that anymore!!!","sourceKey":"Dialog:context:Wife15_FindDialogue4_14","speaker":"{playerName}"},{"number":15,"text":"You come upon Chihaya, who is observing magic wolves in the forest.","sourceKey":"Dialog:context:Wife15_FindDialogue4_Text","speaker":null}]},{"id":"FindWife15_5","characterId":"wife_15","step":"5","lines":[{"number":1,"text":"So you're here to help me again, wonderful. People as kind as you must have many friends. I don't seem to have many friends in my class...","sourceKey":"Dialog:context:Wife15_FindDialogue5_1","speaker":"Chihaya"}]},{"id":"FindWife15_6","characterId":"wife_15","step":"6","lines":[{"number":1,"text":"I bet you think I’m a \"top student?\" I'm not pursuing high grades, to be honest, I'm just studying to satisfy my curiosity.","sourceKey":"Dialog:context:Wife15_FindDialogue6_1","speaker":"Chihaya"}]},{"id":"FindWife15_7","characterId":"wife_15","step":"7","lines":[{"number":1,"text":"Monsters are amazing, they have all sorts of special abilities. Just thinking about it is so interesting. If only I could be reborn as a monster...","sourceKey":"Dialog:context:Wife15_FindDialogue7_1","speaker":"Chihaya"}]},{"id":"FindWife15_8","characterId":"wife_15","step":"8","lines":[{"number":1,"text":"......","sourceKey":"Dialog:context:Wife15_FindDialogue8_1","speaker":"Chihaya"},{"number":2,"text":"The expression on your face is giving me a bad feeling...","sourceKey":"Dialog:context:Wife15_FindDialogue8_2","speaker":"{playerName}"},{"number":3,"text":"You misunderstand, I won’t actually do anything. I just wanted to ask for a small favor...","sourceKey":"Dialog:context:Wife15_FindDialogue8_3","speaker":"Chihaya"},{"number":4,"text":"Please hypnotize me.","sourceKey":"Dialog:context:Wife15_FindDialogue8_4","speaker":"Chihaya"},{"number":5,"text":"You just said you won’t do anything!!!","sourceKey":"Dialog:context:Wife15_FindDialogue8_5","speaker":"{playerName}"},{"number":6,"text":"Chihaya explains that this is also part of her research project: she wants to experience the feeling of being hypnotized firsthand.","sourceKey":"Dialog:context:Wife15_FindDialogue8_6","speaker":null},{"number":7,"text":"You didn't want to agree at first, but eventually she wears you down.","sourceKey":"Dialog:context:Wife15_FindDialogue8_7","speaker":null},{"number":8,"text":"You begin to hypnotize Chihaya according to the instructions in a manual she hands you... As for the result...","sourceKey":"Dialog:context:Wife15_FindDialogue8_8","speaker":null},{"number":9,"text":"Am I... am I hypnotized...? Did it work?","sourceKey":"Dialog:context:Wife15_FindDialogue8_9","speaker":"{playerName}"},{"number":10,"text":"... What's wrong, Master {playerName}?","sourceKey":"Dialog:context:Wife15_FindDialogue8_10","speaker":"Chihaya"},{"number":11,"text":"M-Master!?","sourceKey":"Dialog:context:Wife15_FindDialogue8_11","speaker":"{playerName}"},{"number":12,"text":"I feel so dizzy, I don’t remember anything... Master {playerName}! Did I cause you any trouble?","sourceKey":"Dialog:context:Wife15_FindDialogue8_12","speaker":"Chihaya"},{"number":13,"text":"After being hypnotized, Chihaya's personality seemed to have undergone a drastic change. For a while, you’re at your wits’ end trying to figure out what to do.","sourceKey":"Dialog:context:Wife15_FindDialogue8_13","speaker":null},{"number":14,"text":"After trying a number of things, you finally manage to restore Chihaya to her original state.","sourceKey":"Dialog:context:Wife15_FindDialogue8_14","speaker":null},{"number":15,"text":"Aah...! What... what was I just saying...?","sourceKey":"Dialog:context:Wife15_FindDialogue8_15","speaker":"Chihaya"},{"number":16,"text":"Were you watching the whole time...?","sourceKey":"Dialog:context:Wife15_FindDialogue8_16","speaker":"Chihaya"},{"number":17,"text":"Yeah... Not like I could help it....","sourceKey":"Dialog:context:Wife15_FindDialogue8_17","speaker":"{playerName}"},{"number":18,"text":"Everything seemed to have returned to normal.","sourceKey":"Dialog:context:Wife15_FindDialogue8_18","speaker":null},{"number":19,"text":"One difference, however, is that Chihaya took the initiative to end her field research for the first time.","sourceKey":"Dialog:context:Wife15_FindDialogue8_19","speaker":null},{"number":20,"text":"You feel... a pair of eyes, staring at you...","sourceKey":"Dialog:context:Wife15_FindDialogue8_Text","speaker":null}]},{"id":"FindWife15_9","characterId":"wife_15","step":"9","lines":[{"number":1,"text":"I've finished all my research... Is there anything interesting to do? Anything is fine, let's just do it together.","sourceKey":"Dialog:context:Wife15_FindDialogue9_1","speaker":"Chihaya"}]},{"id":"FindWife15_10","characterId":"wife_15","step":"10","lines":[{"number":1,"text":"It's exam season recently, so I have more free time. Grades? That doesn't matter, scores are meaningless.","sourceKey":"Dialog:context:Wife15_FindDialogue10_1","speaker":"Chihaya"}]},{"id":"FindWife15_11","characterId":"wife_15","step":"11","lines":[{"number":1,"text":"Another batch of freshmen have enrolled, I envy them. Everything is still unknown to them, there are still so many fun things to explore...","sourceKey":"Dialog:context:Wife15_FindDialogue11_1","speaker":"Chihaya"}]},{"id":"FindWife15_12","characterId":"wife_15","step":"12","lines":[{"number":1,"text":"... {playerName}, my vacation is about to start.","sourceKey":"Dialog:context:Wife15_FindDialogue12_1","speaker":"Chihaya"},{"number":2,"text":"Vacation time, is it? This should be a joyful occasion for students, why do you look unhappy?","sourceKey":"Dialog:context:Wife15_FindDialogue12_2","speaker":"{playerName}"},{"number":3,"text":"Vacation... There's no fun in it. Day after day of doing nothing— no projects to work on, just killing time.","sourceKey":"Dialog:context:Wife15_FindDialogue12_3","speaker":"Chihaya"},{"number":4,"text":"That’s not the kind of life I want to lead.","sourceKey":"Dialog:context:Wife15_FindDialogue12_4","speaker":"Chihaya"},{"number":5,"text":"Really? You want to go have fun, Chihaya?","sourceKey":"Dialog:context:Wife15_FindDialogue12_5","speaker":"{playerName}"},{"number":6,"text":"“Fun”... You mean walking around, shopping, that kind of thing?","sourceKey":"Dialog:context:Wife15_FindDialogue12_6","speaker":"Chihaya"},{"number":7,"text":"Lots of things are fun— games, competitions, chatting with friends... You aren’t interested in any of that?","sourceKey":"Dialog:context:Wife15_FindDialogue12_7","speaker":"{playerName}"},{"number":8,"text":"Some of that sounds worth trying... But I’ve never tried before.","sourceKey":"Dialog:context:Wife15_FindDialogue12_8","speaker":"Chihaya"},{"number":9,"text":"Chihaya... have you really never hung out with other people before?","sourceKey":"Dialog:context:Wife15_FindDialogue12_9","speaker":"{playerName}"},{"number":10,"text":"... I have not. Because no one wants to spend time with me.","sourceKey":"Dialog:context:Wife15_FindDialogue12_10","speaker":"Chihaya"},{"number":11,"text":"I've always been alone, whether it's studying or in my free time. So vacation is no fun for me.","sourceKey":"Dialog:context:Wife15_FindDialogue12_11","speaker":"Chihaya"},{"number":12,"text":"Well then, the answer is simple: I’ll hang out with you~","sourceKey":"Dialog:context:Wife15_FindDialogue12_12","speaker":"{playerName}"},{"number":13,"text":"What...?","sourceKey":"Dialog:context:Wife15_FindDialogue12_13","speaker":"Chihaya"},{"number":14,"text":"We've been together for a while now already. If we studied together, we should relax together too!","sourceKey":"Dialog:context:Wife15_FindDialogue12_14","speaker":"{playerName}"},{"number":15,"text":"This is truly... an experience I have never had before... I’m really looking forward to it.","sourceKey":"Dialog:context:Wife15_FindDialogue12_15","speaker":"Chihaya"},{"number":16,"text":"So, {playerName}... we have an agreement. Please spend this vacation with me.","sourceKey":"Dialog:context:Wife15_FindDialogue12_16","speaker":"Chihaya"},{"number":17,"text":"Chihaya seems to be waiting specifically for you.","sourceKey":"Dialog:context:Wife15_FindDialogue12_Text","speaker":null}]},{"id":"FindWife15_13","characterId":"wife_15","step":"13","lines":[{"number":1,"text":"You already know the history and story of every painting in this gallery, and there is nothing more I can tell you. Please, {playerName}, tell me what happens next!","sourceKey":"Dialog:context:Wife15_FindDialogue13_1","speaker":null}]},{"id":"FindWife15_After","characterId":"wife_15","step":"After","lines":[{"number":1,"text":"We're back again. Are you ready, {playerName}? Our vacation will never end.","sourceKey":"Dialog:context:Wife15_FindDialogueAfter_1","speaker":"Chihaya"}]},{"id":"FindWife17_1","characterId":"wife_17","step":"1","lines":[{"number":1,"text":"Where are you going, little girl? Come home with me~","sourceKey":"Dialog:context:Wife17_FindDialogue1_1","speaker":"Male goblin"},{"number":2,"text":"Please don't be like that... I still have work to do...","sourceKey":"Dialog:context:Wife17_FindDialogue1_2","speaker":"Female Elf"},{"number":3,"text":"Then quit working, I'll take care of you~ Hehe, you don’t see such a beautiful elf every day~","sourceKey":"Dialog:context:Wife17_FindDialogue1_3","speaker":"Male goblin"},{"number":4,"text":"Please don't come any closer! He-help me!","sourceKey":"Dialog:context:Wife17_FindDialogue1_4","speaker":"Female Elf"},{"number":5,"text":"An elf hurries away to avoid being harassed by a goblin and accidentally runs right into you.","sourceKey":"Dialog:context:Wife17_FindDialogue1_5","speaker":null},{"number":6,"text":"Oh--! Excuse me...","sourceKey":"Dialog:context:Wife17_FindDialogue1_6","speaker":"Female Elf"},{"number":7,"text":"It's okay, hide behind me and I'll protect you!","sourceKey":"Dialog:context:Wife17_FindDialogue1_7","speaker":"{playerName}"},{"number":8,"text":"You step between her and the goblin and give her aggressor a stern dressing down.","sourceKey":"Dialog:context:Wife17_FindDialogue1_8","speaker":null},{"number":9,"text":"You jerk, it’s broad daylight and you’re already leering at random girls? You should be ashamed!","sourceKey":"Dialog:context:Wife17_FindDialogue1_9","speaker":"{playerName}"},{"number":10,"text":"Tsk! What’s it got to do with you...","sourceKey":"Dialog:context:Wife17_FindDialogue1_10","speaker":"Male goblin"},{"number":11,"text":"The goblin hooligan leaves in a huff.","sourceKey":"Dialog:context:Wife17_FindDialogue1_11","speaker":null},{"number":12,"text":"Jeez, why are there still people like this in Drakenberg... Miss Elf, are you okay?","sourceKey":"Dialog:context:Wife17_FindDialogue1_12","speaker":"{playerName}"},{"number":13,"text":"Wow...","sourceKey":"Dialog:context:Wife17_FindDialogue1_13","speaker":"Female Elf"},{"number":14,"text":"The beautiful elf is staring at you as if in a trance.","sourceKey":"Dialog:context:Wife17_FindDialogue1_14","speaker":null},{"number":15,"text":"Um... what’s going on?","sourceKey":"Dialog:context:Wife17_FindDialogue1_15","speaker":"{playerName}"},{"number":16,"text":"... Aah! Oh handsome and elegant mushroom, my name is Freyja, I come from the Elven Forest. Thank you for saving my life!","sourceKey":"Dialog:context:Wife17_FindDialogue1_16","speaker":"Freyja"},{"number":17,"text":"You're welcome~ My name is {playerName}. (Am I that handsome...? Hehe~)","sourceKey":"Dialog:context:Wife17_FindDialogue1_17","speaker":"{playerName}"},{"number":18,"text":"I really don't know how to thank you. I was entrusted by my elders to guide visitors from other races to visit the Elven Forest, but I got lost and ended up being harassed...","sourceKey":"Dialog:context:Wife17_FindDialogue1_18","speaker":"Freyja"},{"number":19,"text":"I didn’t know how to deal with it, then you descended from the sky like a hero in a story! With your just and righteous words, you drove the monsters off and gently rescued me...","sourceKey":"Dialog:context:Wife17_FindDialogue1_19","speaker":"Freyja"},{"number":20,"text":"That’s a little much, it’s almost embarrassing when you talk like that...","sourceKey":"Dialog:context:Wife17_FindDialogue1_20","speaker":"{playerName}"},{"number":21,"text":"I want to stay with you like this forever, but I still have work to do!","sourceKey":"Dialog:context:Wife17_FindDialogue1_21","speaker":"Freyja"},{"number":22,"text":"It’s like a dream, meeting a hero like {playerName}... No matter what. I don't want this dream to end...","sourceKey":"Dialog:context:Wife17_FindDialogue1_22","speaker":"Freyja"},{"number":23,"text":"Freyja closes her eyes and nestles shyly into your arms. A huge, soft, irresistible sensation presses against your chest and makes your whole body go limp.","sourceKey":"Dialog:context:Wife17_FindDialogue1_23","speaker":null},{"number":24,"text":"Whoa there! Freyja?! I-I bumped into you!","sourceKey":"Dialog:context:Wife17_FindDialogue1_24","speaker":"{playerName}"},{"number":25,"text":"... {playerName}, I don't want our relationship to be just a chance encounter. Remember Freyja, won’t you?","sourceKey":"Dialog:context:Wife17_FindDialogue1_25","speaker":"Freyja"},{"number":26,"text":"O-okay! I'll remember you!","sourceKey":"Dialog:context:Wife17_FindDialogue1_26","speaker":"{playerName}"},{"number":27,"text":"I will finish the work as soon as possible. When it’s done, there won’t be reason for you to stay. But you can come see me anytime, okay?","sourceKey":"Dialog:context:Wife17_FindDialogue1_27","speaker":"Freyja"},{"number":28,"text":"There seems to be an issue at the observation deck.","sourceKey":"Dialog:context:Wife17_FindDialogue1_Text","speaker":null}]},{"id":"FindWife17_2","characterId":"wife_17","step":"2","lines":[{"number":1,"text":"{playerName}! You came to see me~ It's delightful to see your heroic image~","sourceKey":"Dialog:context:Wife17_FindDialogue2_1","speaker":"Freyja"}]},{"id":"FindWife17_3","characterId":"wife_17","step":"3","lines":[{"number":1,"text":"...","sourceKey":"Dialog:context:Wife17_FindDialogue3_1","speaker":"Freyja"},{"number":2,"text":"(Freyja looks so serious. Is she working? Maybe I shouldn't disturb her.)","sourceKey":"Dialog:context:Wife17_FindDialogue3_2","speaker":"{playerName}"},{"number":3,"text":"You quietly approach Freyja and see that her notebook is filled with your name and has a drawing of you.","sourceKey":"Dialog:context:Wife17_FindDialogue3_3","speaker":null},{"number":4,"text":"(Oh!? Is that me?)","sourceKey":"Dialog:context:Wife17_FindDialogue3_4","speaker":"{playerName}"},{"number":5,"text":"Aah! When did you come? You saw everything---! Aahhhh!!","sourceKey":"Dialog:context:Wife17_FindDialogue3_5","speaker":"Freyja"},{"number":6,"text":"Freyja is startled and quickly retreats, accidentally flipping over the railing of the observation deck and falling into the water.","sourceKey":"Dialog:context:Wife17_FindDialogue3_6","speaker":null},{"number":7,"text":"Freyja!!","sourceKey":"Dialog:context:Wife17_FindDialogue3_7","speaker":"{playerName}"},{"number":8,"text":"Without hesitation, you jump into the water and hold onto the struggling Freyja.","sourceKey":"Dialog:context:Wife17_FindDialogue3_8","speaker":null},{"number":9,"text":"Ptui… ptui... Freyja, are you okay?! Luckily, it wasn't long before I took you out of the water; otherwise, you might have drowned.","sourceKey":"Dialog:context:Wife17_FindDialogue3_9","speaker":"{playerName}"},{"number":10,"text":"Although out of the water, Freyja still hasn’t opened her eyes.","sourceKey":"Dialog:context:Wife17_FindDialogue3_10","speaker":null},{"number":11,"text":"Freyja, Freyja! Are you okay?","sourceKey":"Dialog:context:Wife17_FindDialogue3_11","speaker":"{playerName}"},{"number":12,"text":"...{playerName}...","sourceKey":"Dialog:context:Wife17_FindDialogue3_12","speaker":"Freyja"},{"number":13,"text":"Freyja's lips tremble, making a murmuring sound.","sourceKey":"Dialog:context:Wife17_FindDialogue3_13","speaker":null},{"number":14,"text":"Freyja! Can you hear me? Wake up!","sourceKey":"Dialog:context:Wife17_FindDialogue3_14","speaker":"{playerName}"},{"number":15,"text":"{playerName}… is holding me... Is this a dream...?","sourceKey":"Dialog:context:Wife17_FindDialogue3_15","speaker":"Freyja"},{"number":16,"text":"Freyja, you seem to be okay now, how do you feel?","sourceKey":"Dialog:context:Wife17_FindDialogue3_16","speaker":"{playerName}"},{"number":17,"text":"Oww! I feel very weak, I almost drowned, {playerName}!","sourceKey":"Dialog:context:Wife17_FindDialogue3_17","speaker":"Freyja"},{"number":18,"text":"Freyja raises her head slightly, pouting her lips excitedly.","sourceKey":"Dialog:context:Wife17_FindDialogue3_18","speaker":null},{"number":19,"text":"Please help me breathe again...","sourceKey":"Dialog:context:Wife17_FindDialogue3_19","speaker":"Freyja"},{"number":20,"text":"Haven’t you recovered consciousness, though?","sourceKey":"Dialog:context:Wife17_FindDialogue3_20","speaker":"{playerName}"},{"number":21,"text":"Since the moment I saw you, I couldn't keep a clear head, {playerName}! Since we parted, I couldn't help but think of you constantly.","sourceKey":"Dialog:context:Wife17_FindDialogue3_21","speaker":"Freyja"},{"number":22,"text":"I've never felt this way before I met you, you are the one I'm destined to be with!","sourceKey":"Dialog:context:Wife17_FindDialogue3_22","speaker":"Freyja"},{"number":23,"text":"Freyja...","sourceKey":"Dialog:context:Wife17_FindDialogue3_23","speaker":"{playerName}"},{"number":24,"text":"{playerName}...","sourceKey":"Dialog:context:Wife17_FindDialogue3_24","speaker":"Freyja"},{"number":25,"text":"We shouldn’t talk about this right now… Let's get on the pier first, and then we can talk!","sourceKey":"Dialog:context:Wife17_FindDialogue3_25","speaker":"{playerName}"},{"number":26,"text":"Freyja is quiet, lost in her thoughts while writing something in her notebook.","sourceKey":"Dialog:context:Wife17_FindDialogue3_Text","speaker":null}]},{"id":"FindWife17_4","characterId":"wife_17","step":"4","lines":[{"number":1,"text":"The Elves live in Elven Forest, where we rely on the natural magic here to live. Although it is open to the outside, there are always rash people getting lost, so I am responsible for being a guide here.","sourceKey":"Dialog:context:Wife17_FindDialogue4_1","speaker":null}]},{"id":"FindWife17_5","characterId":"wife_17","step":"5","lines":[{"number":1,"text":"Since I have already told you so much about the elves, please tell me the story of you and your village in the coming days. Hehe, the elf's ears are very sensitive, you know, they can hear all kinds of news.","sourceKey":"Dialog:context:Wife17_FindDialogue5_1","speaker":null}]},{"id":"FindWife17_6","characterId":"wife_17","step":"6","lines":[{"number":1,"text":"Outsiders expect much from elves, but we also yearn for the outside world and its enchanting life, just like your village. It sounds so beautiful, like a fairy tale.","sourceKey":"Dialog:context:Wife17_FindDialogue6_1","speaker":null}]},{"id":"FindWife17_7","characterId":"wife_17","step":"7","lines":[{"number":1,"text":"Elves have long lifespan, so we usually don't build relationships with other races to avoid the pain of separation and loss. Sorry for mentioning the sad topic. I apologize for talking too much.","sourceKey":"Dialog:context:Wife17_FindDialogue7_1","speaker":null}]},{"id":"FindWife17_8","characterId":"wife_17","step":"8","lines":[{"number":1,"text":"There's been a subtle gap between outsiders and us for long. We can enjoy the surprise of mystery. But that also causes us to lose the chance to know each other. It may not be bad if we get closer, right?","sourceKey":"Dialog:context:Wife17_FindDialogue8_1","speaker":null}]},{"id":"FindWife17_9","characterId":"wife_17","step":"9","lines":[{"number":1,"text":"If your village can really bridge the gap between races...I hope I'm not being rude, but would you be willing to accept an elf who wants to learn more about you?","sourceKey":"Dialog:context:Wife17_FindDialogue9_1","speaker":null}]},{"id":"FindWife17_After","characterId":"wife_17","step":"After","lines":[{"number":1,"text":"Every time I come here, I remember the wonderful scenes when I met {playerName}...","sourceKey":"Dialog:context:Wife17_FindDialogueAfter_1","speaker":"Freyja"}]},{"id":"FindWife18_1","characterId":"wife_18","step":"1","lines":[{"number":1,"text":"Please pay, lady. Stop playing.","sourceKey":"Dialog:context:Wife18_FindDialogue1_1","speaker":"Clerk"},{"number":2,"text":"What's wrong? I paid the correct amount.","sourceKey":"Dialog:context:Wife18_FindDialogue1_2","speaker":"Mysterious witch"},{"number":3,"text":"What currency is this? I have never seen it. We cannot accept it!","sourceKey":"Dialog:context:Wife18_FindDialogue1_3","speaker":"Clerk"},{"number":4,"text":"Huh? This is genuine gold, why wouldn’t you accept it?","sourceKey":"Dialog:context:Wife18_FindDialogue1_4","speaker":"Mysterious witch"},{"number":5,"text":"What are you saying? Are you trying to rip us off?!","sourceKey":"Dialog:context:Wife18_FindDialogue1_5","speaker":"Clerk"},{"number":6,"text":"Umm, let me pay for her. This noise disturbs other customers.","sourceKey":"Dialog:context:Wife18_FindDialogue1_6","speaker":"{playerName}"},{"number":7,"text":"You pay for the stranger woman's coffee and leave the coffee shop with her.","sourceKey":"Dialog:context:Wife18_FindDialogue1_7","speaker":null},{"number":8,"text":"Thank you so much! Thank you for helping me solve this problem. If it hadn’t been for you, another war might have started… You are a true hero!","sourceKey":"Dialog:context:Wife18_FindDialogue1_8","speaker":"Mysterious witch"},{"number":9,"text":"Really? Starting a war for such a small matter, no way! Haha.","sourceKey":"Dialog:context:Wife18_FindDialogue1_9","speaker":"{playerName}"},{"number":10,"text":"Thank you for helping me. My name is Catherine. May I ask for your name?","sourceKey":"Dialog:context:Wife18_FindDialogue1_10","speaker":"Catherine"},{"number":11,"text":"Just call me {playerName}. It's just a cup of coffee, no need to thank me. Everyone forgets their money sometimes.","sourceKey":"Dialog:context:Wife18_FindDialogue1_11","speaker":"{playerName}"},{"number":12,"text":"But I didn’t forget my money. The cashier just wouldn't take my money for some reason.","sourceKey":"Dialog:context:Wife18_FindDialogue1_12","speaker":"Catherine"},{"number":13,"text":"Let me give you back the money, okay?","sourceKey":"Dialog:context:Wife18_FindDialogue1_13","speaker":"Catherine"},{"number":14,"text":"Catherine puts two ancient-looking coins in your hand.","sourceKey":"Dialog:context:Wife18_FindDialogue1_14","speaker":null},{"number":15,"text":"W-what kind of money is this? I've never seen it before...","sourceKey":"Dialog:context:Wife18_FindDialogue1_15","speaker":"{playerName}"},{"number":16,"text":"Detecting ancient relics of a lost civilization. Estimated issuing period: 300 years ago.","sourceKey":"Dialog:context:Wife18_FindDialogue1_16","speaker":"Erica"},{"number":17,"text":"Three hundred years?! It is already an antique and hasn't been in circulation for long. Why would you use something like this as money?","sourceKey":"Dialog:context:Wife18_FindDialogue1_17","speaker":"{playerName}"},{"number":18,"text":"So it's not in circulation anymore, huh? It used to be something everyone fought over during those days.","sourceKey":"Dialog:context:Wife18_FindDialogue1_18","speaker":"Catherine"},{"number":19,"text":"During those days... Excuse me, what do you mean by \"during those days\"?","sourceKey":"Dialog:context:Wife18_FindDialogue1_19","speaker":"{playerName}"},{"number":20,"text":"Hmm… it's been about three hundred years?","sourceKey":"Dialog:context:Wife18_FindDialogue1_20","speaker":"Catherine"},{"number":21,"text":"How is this possible?! Are you over three hundred years old...?","sourceKey":"Dialog:context:Wife18_FindDialogue1_21","speaker":"{playerName}"},{"number":22,"text":"Oh dear, age is a taboo topic for a witch~","sourceKey":"Dialog:context:Wife18_FindDialogue1_22","speaker":"Catherine"},{"number":23,"text":"I've forgotten the exact time. I just remember there were frequent wars here a long time ago. To avoid the war, I started living a seclusive life.","sourceKey":"Dialog:context:Wife18_FindDialogue1_23","speaker":"Catherine"},{"number":24,"text":"I've gradually stopped feeling the atmosphere of war recently, so I wanted to go back to the city and take a look.","sourceKey":"Dialog:context:Wife18_FindDialogue1_24","speaker":"Catherine"},{"number":25,"text":"However, I didn't expect I couldn't even use the gold I saved up, and almost triggered a new war...","sourceKey":"Dialog:context:Wife18_FindDialogue1_25","speaker":"Catherine"},{"number":26,"text":"(Hmm... have there been any wars here in the past?)","sourceKey":"Dialog:context:Wife18_FindDialogue1_26","speaker":"{playerName}"},{"number":27,"text":"(But I've been living here for a long time and it’s pretty peaceful…)","sourceKey":"Dialog:context:Wife18_FindDialogue1_27","speaker":"{playerName}"},{"number":28,"text":"I've been living here for a while, and I feel like it's a peaceful place. If you stay here longer, you'll definitely fall in love with it.","sourceKey":"Dialog:context:Wife18_FindDialogue1_28","speaker":"{playerName}"},{"number":29,"text":"Hmm... what you say makes sense. I think there is no use in keep hiding. I should spend some time integrating into the society.","sourceKey":"Dialog:context:Wife18_FindDialogue1_29","speaker":"Catherine"},{"number":30,"text":"But I'll start trying my best from tomorrow. I'm done for today...","sourceKey":"Dialog:context:Wife18_FindDialogue1_30","speaker":"Catherine"},{"number":31,"text":"But you only had a cup of coffee, hah. (Does it become hard to enjoy life after living in seclusion for so long...?)","sourceKey":"Dialog:context:Wife18_FindDialogue1_31","speaker":"{playerName}"},{"number":32,"text":"The coffee shop becomes a bit noisy.","sourceKey":"Dialog:context:Wife18_FindDialogue1_Text","speaker":null}]},{"id":"FindWife18_2","characterId":"wife_18","step":"2","lines":[{"number":1,"text":"{playerName}, have you come to help me understand these times? Thank you so much! I've been studying the language in use these days for some time and have learned to spell your name~","sourceKey":"Dialog:context:Wife18_FindDialogue2_1","speaker":"Catherine"}]},{"id":"FindWife18_3","characterId":"wife_18","step":"3","lines":[{"number":1,"text":"I've read some books recording the history of three hundred years ago. Somehow there seem to be many discrepancies between the records and my own experiences. Is it that my memory is failing?","sourceKey":"Dialog:context:Wife18_FindDialogue3_1","speaker":"Catherine"}]},{"id":"FindWife18_4","characterId":"wife_18","step":"4","lines":[{"number":1,"text":"{playerName}, nice to see you again~ Thank you for your generosity last time. I can treat you to a cup of coffee soon~","sourceKey":"Dialog:context:Wife18_FindDialogue4_1","speaker":"Catherine"},{"number":2,"text":"No need, haha. But how would you pay? Those ancient coins you have can't be used in modern times.","sourceKey":"Dialog:context:Wife18_FindDialogue4_2","speaker":"{playerName}"},{"number":3,"text":"I was also troubled by this matter, but then some self-proclaimed collectors heard I had these coins and came to me one after another.","sourceKey":"Dialog:context:Wife18_FindDialogue4_3","speaker":"Catherine"},{"number":4,"text":"They offered to buy all my belongings at a high price. If I sell my things to them, I'll have enough money to treat you to coffee~","sourceKey":"Dialog:context:Wife18_FindDialogue4_4","speaker":"Catherine"},{"number":5,"text":"Thinking about it, your belongings, even the most ordinary in daily life, are rare artifacts in the eyes of people now.","sourceKey":"Dialog:context:Wife18_FindDialogue4_5","speaker":"{playerName}"},{"number":6,"text":"Don’t mind the coffee. If you sell your things, you'll be rolling in money!","sourceKey":"Dialog:context:Wife18_FindDialogue4_6","speaker":"{playerName}"},{"number":7,"text":"So, have you decided who to sell to?","sourceKey":"Dialog:context:Wife18_FindDialogue4_7","speaker":"{playerName}"},{"number":8,"text":"Hmm, I don't really understand these things. To be honest, those collectors are very aggressive about competing with each other on prices, which is quite troublesome.","sourceKey":"Dialog:context:Wife18_FindDialogue4_8","speaker":"Catherine"},{"number":9,"text":"It would be terrible if this competition eventually evolves into a war...","sourceKey":"Dialog:context:Wife18_FindDialogue4_9","speaker":"Catherine"},{"number":10,"text":"I’ve told you. A war shouldn’t break out for such a small thing.","sourceKey":"Dialog:context:Wife18_FindDialogue4_10","speaker":"{playerName}"},{"number":11,"text":"Moreover, each of them is only interested in specific types of items, so I have to negotiate with many people separately to sell everything.","sourceKey":"Dialog:context:Wife18_FindDialogue4_11","speaker":"Catherine"},{"number":12,"text":"Humph, it's so tiring to think about... If only someone could take them all away at once. Oh, and it would be even better if they could come to my home to collect them!","sourceKey":"Dialog:context:Wife18_FindDialogue4_12","speaker":"Catherine"},{"number":13,"text":"I don't think there's such a buyer. It's unlikely.","sourceKey":"Dialog:context:Wife18_FindDialogue4_13","speaker":"{playerName}"},{"number":14,"text":"Before the words were out of your mouth, someone delivered a letter to Catherine.","sourceKey":"Dialog:context:Wife18_FindDialogue4_14","speaker":null},{"number":15,"text":"Oh, another letter has arrived. It must be from a collector. Let me see…","sourceKey":"Dialog:context:Wife18_FindDialogue4_15","speaker":"Catherine"},{"number":16,"text":"Catherine looks at the letter showing a surprised expression, then smiles happily.","sourceKey":"Dialog:context:Wife18_FindDialogue4_16","speaker":null},{"number":17,"text":"Great news, {playerName}! I've found a buyer who will take everything without any problem.","sourceKey":"Dialog:context:Wife18_FindDialogue4_17","speaker":"Catherine"},{"number":18,"text":"The gentleman in the letter wants to buy all my belongings and will send someone to inspect and pick them up. I don't have to do anything to complete the trade.","sourceKey":"Dialog:context:Wife18_FindDialogue4_18","speaker":"Catherine"},{"number":19,"text":"What?! Is there really such a buyer? Who is he?","sourceKey":"Dialog:context:Wife18_FindDialogue4_19","speaker":"{playerName}"},{"number":20,"text":"Hmm... It seems his name is \"Museum\"?","sourceKey":"Dialog:context:Wife18_FindDialogue4_20","speaker":"Catherine"},{"number":21,"text":"A museum? (No wonder. They said they would buy it, but it's more like a donation. Their offer must be very low).","sourceKey":"Dialog:context:Wife18_FindDialogue4_21","speaker":"{playerName}"},{"number":22,"text":"Catherine, can you check how much they're willing to pay?","sourceKey":"Dialog:context:Wife18_FindDialogue4_22","speaker":"{playerName}"},{"number":23,"text":"Let me see... it says… one bag of gold coins.","sourceKey":"Dialog:context:Wife18_FindDialogue4_23","speaker":"Catherine"},{"number":24,"text":"Just what I expected! That’s too little! These are antiques from three hundred years ago! Each one alone is worth that much!","sourceKey":"Dialog:context:Wife18_FindDialogue4_24","speaker":"{playerName}"},{"number":25,"text":"But selling to “Museum” can save me a lot of trouble, and it won't be a hassle anymore.","sourceKey":"Dialog:context:Wife18_FindDialogue4_25","speaker":"Catherine"},{"number":26,"text":"The amount of money isn’t that important. No one can predict what will happen tomorrow, and you can lose your wealth at any time.","sourceKey":"Dialog:context:Wife18_FindDialogue4_26","speaker":"Catherine"},{"number":27,"text":"This bag of gold coins... as long as it can buy today's coffee, it's good enough.","sourceKey":"Dialog:context:Wife18_FindDialogue4_27","speaker":"Catherine"},{"number":28,"text":"Catherine holds a bunch of ancient books in her hands.","sourceKey":"Dialog:context:Wife18_FindDialogue4_Text","speaker":null}]},{"id":"FindWife18_5","characterId":"wife_18","step":"5","lines":[{"number":1,"text":"The children I encounter on the road call me “miss,” hehe. If you want to stay young, just relax and enjoy life like me~","sourceKey":"Dialog:context:Wife18_FindDialogue5_1","speaker":"Catherine"}]},{"id":"FindWife18_6","characterId":"wife_18","step":"6","lines":[{"number":1,"text":"I can't believe modern magic is so complex. The research on it is also really difficult. Back then, lighting a fire with wood was already impressive.","sourceKey":"Dialog:context:Wife18_FindDialogue6_1","speaker":"Catherine"}]},{"id":"FindWife18_7","characterId":"wife_18","step":"7","lines":[{"number":1,"text":"Would you like a cup of tea? This blend is nothing like what you have these days~","sourceKey":"Dialog:context:Wife18_FindDialogue7_1","speaker":"Catherine"}]},{"id":"FindWife18_8","characterId":"wife_18","step":"8","lines":[{"number":1,"text":"You scoundrel! Why did you steal my Cat?","sourceKey":"Dialog:context:Wife18_FindDialogue8_1","speaker":"Male goblin"},{"number":2,"text":"A goblin holding a cat scolds angrily at Catherine, and you notice she is scared.","sourceKey":"Dialog:context:Wife18_FindDialogue8_2","speaker":null},{"number":3,"text":"I-I didn’t... do anything...","sourceKey":"Dialog:context:Wife18_FindDialogue8_3","speaker":"Catherine"},{"number":4,"text":"Catherine? Are you okay?","sourceKey":"Dialog:context:Wife18_FindDialogue8_4","speaker":"{playerName}"},{"number":5,"text":"You make the goblin calm down and bring Catherine aside, comforting her.","sourceKey":"Dialog:context:Wife18_FindDialogue8_5","speaker":null},{"number":6,"text":"It's alright, calm down… Can you tell me what happened?","sourceKey":"Dialog:context:Wife18_FindDialogue8_6","speaker":"{playerName}"},{"number":7,"text":"I-I was just drinking coffee here as usual, and then a little cat suddenly came to me running.","sourceKey":"Dialog:context:Wife18_FindDialogue8_7","speaker":"Catherine"},{"number":8,"text":"I thought it was cute, so I fed it something, but not long after, that goblin came over and accused me of stealing his cat...","sourceKey":"Dialog:context:Wife18_FindDialogue8_8","speaker":"Catherine"},{"number":9,"text":"{playerName}... what should I do? Is this hard-won peace going to be broken because of me...","sourceKey":"Dialog:context:Wife18_FindDialogue8_9","speaker":"Catherine"},{"number":10,"text":"No! Don't be afraid. A war won't break out for such trifles. Don't tell me a war broke out 300 years ago just because a cat was stolen. ","sourceKey":"Dialog:context:Wife18_FindDialogue8_10","speaker":"{playerName}"},{"number":11,"text":"Yes... a human king kidnapped a cat raised by the dragons, and the largest-scale war broke out...","sourceKey":"Dialog:context:Wife18_FindDialogue8_11","speaker":"Catherine"},{"number":12,"text":"For real?! A whole-scale war started for such a thing?!","sourceKey":"Dialog:context:Wife18_FindDialogue8_12","speaker":"{playerName}"},{"number":13,"text":"Three hundred years ago, races were hostile to each other. Although it was later proved to be all a misunderstanding, no one cared.","sourceKey":"Dialog:context:Wife18_FindDialogue8_13","speaker":"Catherine"},{"number":14,"text":"As the world was in the midst of war, I escaped to the Tranquil Forest because I couldn't bear it and began to live in seclusion…","sourceKey":"Dialog:context:Wife18_FindDialogue8_14","speaker":"Catherine"},{"number":15,"text":"Catherine, have you explained what happened with the cat just now to the Goblin?","sourceKey":"Dialog:context:Wife18_FindDialogue8_15","speaker":"{playerName}"},{"number":16,"text":"Explanations are meaningless... I am a witch, and everyone will think I stole the cat… no one will listen...","sourceKey":"Dialog:context:Wife18_FindDialogue8_16","speaker":"Catherine"},{"number":17,"text":"(It seems the war 300 years ago had a great impact on Catherine, and she hasn't been able to overcome that… I need to help her.)","sourceKey":"Dialog:context:Wife18_FindDialogue8_17","speaker":"{playerName}"},{"number":18,"text":"Catherine, come with me.","sourceKey":"Dialog:context:Wife18_FindDialogue8_18","speaker":"{playerName}"},{"number":19,"text":"Holding Catherine's hand, you face the angry goblin.","sourceKey":"Dialog:context:Wife18_FindDialogue8_19","speaker":null},{"number":20,"text":"Sir, my friend didn't steal your cat. She just happened to come across it while drinking coffee here.","sourceKey":"Dialog:context:Wife18_FindDialogue8_20","speaker":"{playerName}"},{"number":21,"text":"You came here right after your cat went missing, right? But if she really wanted to steal your cat, why would she stay instead of running away?","sourceKey":"Dialog:context:Wife18_FindDialogue8_21","speaker":"{playerName}"},{"number":22,"text":"The customers and staff should be able to testify as well.","sourceKey":"Dialog:context:Wife18_FindDialogue8_22","speaker":"{playerName}"},{"number":23,"text":"To prove your point, you ask some people in the shop. They all deny Catherine stealing the cat.","sourceKey":"Dialog:context:Wife18_FindDialogue8_23","speaker":null},{"number":24,"text":"Ahh… I'm sorry! I was too worried about my cat and wrongly accused you guys!","sourceKey":"Dialog:context:Wife18_FindDialogue8_24","speaker":"Male goblin"},{"number":25,"text":"I... I'll treat you guys to coffee!","sourceKey":"Dialog:context:Wife18_FindDialogue8_25","speaker":"Male goblin"},{"number":26,"text":"The fierce-looking goblin bought two large cups of coffee for you and Catherine, and after apologizing again, he left with the cat.","sourceKey":"Dialog:context:Wife18_FindDialogue8_26","speaker":null},{"number":27,"text":"I can't believe it... The problem was resolved so easily...","sourceKey":"Dialog:context:Wife18_FindDialogue8_27","speaker":"Catherine"},{"number":28,"text":"See? This is the way people resolve conflicts nowadays.","sourceKey":"Dialog:context:Wife18_FindDialogue8_28","speaker":"{playerName}"},{"number":29,"text":"Now, communication and exchange are the methods we use to resolve conflicts. We won't easily go to war anymore, so don't worry~","sourceKey":"Dialog:context:Wife18_FindDialogue8_29","speaker":"{playerName}"},{"number":30,"text":"Hmm, I think I now fully understand the ways of this city. Thank you very much, {playerName}.","sourceKey":"Dialog:context:Wife18_FindDialogue8_30","speaker":"Catherine"},{"number":31,"text":"There seems to be an issue at the coffee shop's entrance.","sourceKey":"Dialog:context:Wife18_FindDialogue8_Text","speaker":null}]},{"id":"FindWife18_9","characterId":"wife_18","step":"9","lines":[{"number":1,"text":"Later, that goblin gentleman brought the cat here to play with me~ A peaceful world is really beautiful~","sourceKey":"Dialog:context:Wife18_FindDialogue9_1","speaker":"Catherine"}]},{"id":"FindWife18_10","characterId":"wife_18","step":"10","lines":[{"number":1,"text":"Every evening, I can see many children passing by here after school, excitedly telling their parents about their wonderful experiences of the day… Seeing such a scene really makes one happy. ","sourceKey":"Dialog:context:Wife18_FindDialogue10_1","speaker":"Catherine"}]},{"id":"FindWife18_11","characterId":"wife_18","step":"11","lines":[{"number":1,"text":"Some mages recently invited me to join their war research. I thought it was another ominous omen, but it turned out they were just playing a tabletop game simulating war…","sourceKey":"Dialog:context:Wife18_FindDialogue11_1","speaker":"Catherine"}]},{"id":"FindWife18_12","characterId":"wife_18","step":"12","lines":[{"number":1,"text":"So magic no longer serves destruction...hehe~ If it had been like this three hundred years ago, I might have been more interested in learning~","sourceKey":"Dialog:context:Wife18_FindDialogue12_1","speaker":"Catherine"}]},{"id":"FindWife18_13","characterId":"wife_18","step":"13","lines":[{"number":1,"text":"Catherine sits on a table she set up outdoors. The table has tea and accompanying pastries served.","sourceKey":"Dialog:context:Wife18_FindDialogue13_1","speaker":null},{"number":2,"text":"{playerName}~ come over here~","sourceKey":"Dialog:context:Wife18_FindDialogue13_2","speaker":"Catherine"},{"number":3,"text":"Hello Catherine, wow, those pastries look neat...","sourceKey":"Dialog:context:Wife18_FindDialogue13_3","speaker":"{playerName}"},{"number":4,"text":"Hehe~ I've been preparing for a long time, just to invite you to this \"Witch's Tea Party\"~","sourceKey":"Dialog:context:Wife18_FindDialogue13_4","speaker":"Catherine"},{"number":5,"text":"Catherine pours you a cup of hot tea and invites you to take a seat.","sourceKey":"Dialog:context:Wife18_FindDialogue13_5","speaker":null},{"number":6,"text":"The tea is so fragrant. Thank you for inviting me over. Is the Witches' Tea Party some tradition? I think I've read about it.","sourceKey":"Dialog:context:Wife18_FindDialogue13_6","speaker":"{playerName}"},{"number":7,"text":"This is a tradition that has existed for a long time, exclusively for witches.","sourceKey":"Dialog:context:Wife18_FindDialogue13_7","speaker":"Catherine"},{"number":8,"text":"Three hundred years ago, the world was in constant turmoil, and the Witch’s Tea Party was the only time we could have some peace during the war.","sourceKey":"Dialog:context:Wife18_FindDialogue13_8","speaker":"Catherine"},{"number":9,"text":"My friends and I agreed to hold tea parties regularly no matter where we were.","sourceKey":"Dialog:context:Wife18_FindDialogue13_9","speaker":"Catherine"},{"number":10,"text":"At the Witch's Tea Party, we forget all our problems for some time and enjoy life.","sourceKey":"Dialog:context:Wife18_FindDialogue13_10","speaker":"Catherine"},{"number":11,"text":"However, over time, my witch friends parted for various reasons... In the end, I became the only one who could celebrate this tradition.","sourceKey":"Dialog:context:Wife18_FindDialogue13_11","speaker":"Catherine"},{"number":12,"text":"As I began to seclude myself, the Witch's Tea Party wasn’t held again until today.","sourceKey":"Dialog:context:Wife18_FindDialogue13_12","speaker":"Catherine"},{"number":13,"text":"Wow, then it’s my pleasure to attend this important celebration.","sourceKey":"Dialog:context:Wife18_FindDialogue13_13","speaker":"{playerName}"},{"number":14,"text":"Hehe~ this tea party, which had been suspended for such a long time, welcomes you and should have new meanings...","sourceKey":"Dialog:context:Wife18_FindDialogue13_14","speaker":"Catherine"},{"number":15,"text":"{playerName}, before meeting you, I had so many doubts about this new era. If it hadn’t been for you, I might have run away again...","sourceKey":"Dialog:context:Wife18_FindDialogue13_15","speaker":"Catherine"},{"number":16,"text":"You’ve helped me understand what peace is, and now I can finally face my thoughts without fear.","sourceKey":"Dialog:context:Wife18_FindDialogue13_16","speaker":"Catherine"},{"number":17,"text":"I want to be part of this era. I want to start a new life here.","sourceKey":"Dialog:context:Wife18_FindDialogue13_17","speaker":"Catherine"},{"number":18,"text":"And if, by any chance, conflicts and disputes arise again, I don't want to run away anymore...","sourceKey":"Dialog:context:Wife18_FindDialogue13_18","speaker":"Catherine"},{"number":19,"text":"Because this era is beautiful enough for me to not want to give up... This time, I want to work hard to make these times even better.","sourceKey":"Dialog:context:Wife18_FindDialogue13_19","speaker":"Catherine"},{"number":20,"text":"I'm not sure what you went through three hundred years ago, but I believe that this era won’t let you down.","sourceKey":"Dialog:context:Wife18_FindDialogue13_20","speaker":"{playerName}"},{"number":21,"text":"Of course, if times of conflict ever come again, I will be by your side.","sourceKey":"Dialog:context:Wife18_FindDialogue13_21","speaker":"{playerName}"},{"number":22,"text":"For you, and for this world that I love, I will do my best to maintain peace.","sourceKey":"Dialog:context:Wife18_FindDialogue13_22","speaker":"{playerName}"},{"number":23,"text":"However, {playerName}... let's start striving from tomorrow~","sourceKey":"Dialog:context:Wife18_FindDialogue13_23","speaker":"Catherine"},{"number":24,"text":"Huh?","sourceKey":"Dialog:context:Wife18_FindDialogue13_24","speaker":"{playerName}"},{"number":25,"text":"After all, peaceful times are all around in this city~","sourceKey":"Dialog:context:Wife18_FindDialogue13_25","speaker":"Catherine"},{"number":26,"text":"Hahaha! You're right. Let's just keep pushing this effort infinitely to tomorrow~","sourceKey":"Dialog:context:Wife18_FindDialogue13_26","speaker":"{playerName}"},{"number":27,"text":"You and Catherine raise your cups and toast to the \"efforts\" that will never come.","sourceKey":"Dialog:context:Wife18_FindDialogue13_27","speaker":null},{"number":28,"text":"Catherine is waiting for you outside the coffee shop.","sourceKey":"Dialog:context:Wife18_FindDialogue13_Text","speaker":null}]},{"id":"FindWife18_After","characterId":"wife_18","step":"After","lines":[{"number":1,"text":"Well, the taste of this coffee really brings back some memories... What do you think?","sourceKey":"Dialog:context:Wife18_FindDialogueAfter_1","speaker":"Catherine"}]},{"id":"FindWife53_1","characterId":"wife_53","step":"1","lines":[{"number":1,"text":"Lots of people are around each painting. It seems there are many famous masterpieces in this exhibition.","sourceKey":"Dialog:context:Wife53_FindDialogue1_1","speaker":"{playerName}"},{"number":2,"text":"However, you notice one of the paintings is on display yet with no one around viewing it.","sourceKey":"Dialog:context:Wife53_FindDialogue1_2","speaker":null},{"number":3,"text":"(Huh? Why isn't anyone appreciating this painting? Let me see...)","sourceKey":"Dialog:context:Wife53_FindDialogue1_3","speaker":"{playerName}"},{"number":4,"text":"(…It is actually a really impressive painting. Especially its colors, incredibly vibrant yet not noisy at all.)","sourceKey":"Dialog:context:Wife53_FindDialogue1_4","speaker":"{playerName}"},{"number":5,"text":"At this moment, some visitors find you appreciating this painting and start whispering behind you.","sourceKey":"Dialog:context:Wife53_FindDialogue1_5","speaker":null},{"number":6,"text":"I don't expect someone dares to approach that painting… Seems that he's going to be possessed by a ghost.","sourceKey":"Dialog:context:Wife53_FindDialogue1_6","speaker":"Talking visitors"},{"number":7,"text":"(What!? Ghost? Why would there be a ghost in the gallery… So no one views this painting because it's cursed?)","sourceKey":"Dialog:context:Wife53_FindDialogue1_7","speaker":"{playerName}"},{"number":8,"text":"(I don't know if it's my imagination or anything… I really do feel like I'm being stared by something else… Could it really be a ghost!?)","sourceKey":"Dialog:context:Wife53_FindDialogue1_8","speaker":"{playerName}"},{"number":9,"text":"You turn around and find nothing.","sourceKey":"Dialog:context:Wife53_FindDialogue1_9","speaker":null},{"number":10,"text":"(This… this place is haunted! What should I do… huh? I feel like there's something in front of me.)","sourceKey":"Dialog:context:Wife53_FindDialogue1_10","speaker":"{playerName}"},{"number":11,"text":"You slowly reach out towards the empty space in front and unexpectedly feel a soft touch followed by a scream.","sourceKey":"Dialog:context:Wife53_FindDialogue1_11","speaker":null},{"number":12,"text":"Ahhhhhh—! Don't… don't touch my tail—!","sourceKey":"Dialog:context:Wife53_FindDialogue1_12","speaker":"???"},{"number":13,"text":"W-W-What!? Who… who are you? How did you suddenly appear in front of me!?","sourceKey":"Dialog:context:Wife53_FindDialogue1_13","speaker":"{playerName}"},{"number":14,"text":"Wahhhh! I… I am exposed… *Sob* Sorry… I-I didn't mean to scare you! I-I…","sourceKey":"Dialog:context:Wife53_FindDialogue1_14","speaker":"???"},{"number":15,"text":"(Is she a… chameleon? So that's why she can hide herself...) I'm fine. I think you need to calm down for a moment…","sourceKey":"Dialog:context:Wife53_FindDialogue1_15","speaker":"{playerName}"},{"number":16,"text":"Phew… Um, I-I'm Merry… I didn't mean to scare you! It-it's just that… finally… someone is willing to view my painting…","sourceKey":"Dialog:context:Wife53_FindDialogue1_16","speaker":"Merry"},{"number":17,"text":"Your painting? So this is your work? It's really amazing!","sourceKey":"Dialog:context:Wife53_FindDialogue1_17","speaker":"{playerName}"},{"number":18,"text":"Eek! I-I'm flattered! I-I-I… hehe… thank you for your compliment…","sourceKey":"Dialog:context:Wife53_FindDialogue1_18","speaker":"Merry"},{"number":19,"text":"Merry's painting is really good. In fact, it's strange that no one has come to view such an impressive work.","sourceKey":"Dialog:context:Wife53_FindDialogue1_19","speaker":"{playerName}"},{"number":20,"text":"*Sob* I've heard from others… it's because of the ghost… that no one dares to view my painting…","sourceKey":"Dialog:context:Wife53_FindDialogue1_20","speaker":"Merry"},{"number":21,"text":"(Is it the rumor I heard before? It's so strange. Why would a ghost come to harass the guests at the exhibition?)","sourceKey":"Dialog:context:Wife53_FindDialogue1_21","speaker":"{playerName}"},{"number":22,"text":"Right at this moment, two visitors walked towards this painting.","sourceKey":"Dialog:context:Wife53_FindDialogue1_22","speaker":null},{"number":23,"text":"This is my first time attending an art exhibition. There are so many interesting works… Wow, look at that painting! Amazing color!","sourceKey":"Dialog:context:Wife53_FindDialogue1_23","speaker":"Talking visitors"},{"number":24,"text":"I didn't expect to see a colourist painting… It reminds me of Master Rollin's works. Let's get closer for a better view~","sourceKey":"Dialog:context:Wife53_FindDialogue1_24","speaker":"Talking visitors"},{"number":25,"text":"(They seem to be new visitors and they are attracted by Merry's work at first sight. Great… Wait, where is Merry?)","sourceKey":"Dialog:context:Wife53_FindDialogue1_25","speaker":"{playerName}"},{"number":26,"text":"In the blink of an eye, Merry disappeared without a trace, and you can only see two visitors admiring the painting.","sourceKey":"Dialog:context:Wife53_FindDialogue1_26","speaker":null},{"number":27,"text":"It's really an impressive work… However, I feel a little bit uncomfortable after getting closer, as if something is staring at me.","sourceKey":"Dialog:context:Wife53_FindDialogue1_27","speaker":"Talking visitors"},{"number":28,"text":"Me too! But there's nothing behind me obviously… I'm scared. Let's…let's get out of here soon!","sourceKey":"Dialog:context:Wife53_FindDialogue1_28","speaker":"Talking visitors"},{"number":29,"text":"After two visitors leave in a hurry, you see Merry slowly appearing again.","sourceKey":"Dialog:context:Wife53_FindDialogue1_29","speaker":null},{"number":30,"text":"I-I was scared to death just now…! I didn't expect someone to come so soon… But they are still frightened away by ghost… *Sigh*","sourceKey":"Dialog:context:Wife53_FindDialogue1_30","speaker":"Merry"},{"number":31,"text":"Who scared who! It seems that you are the ghost!","sourceKey":"Dialog:context:Wife53_FindDialogue1_31","speaker":"{playerName}"},{"number":32,"text":"An art exhibition is being held in the gallery.","sourceKey":"Dialog:context:Wife53_FindDialogue1_Text","speaker":null}]},{"id":"FindWife53_2","characterId":"wife_53","step":"2","lines":[{"number":1,"text":"It's really rare to see Merry not hiding herself today~","sourceKey":"Dialog:context:Wife53_FindDialogue2_1","speaker":"{playerName}"},{"number":2,"text":"…{playerName}!? It's you… You scared me… I-I'm practicing… for my debut interview…","sourceKey":"Dialog:context:Wife53_FindDialogue2_2","speaker":"Merry"},{"number":3,"text":"After meeting {playerName}, I tried to gather my courage… and stopped hiding any more… So more and more people are willing to see my painting…","sourceKey":"Dialog:context:Wife53_FindDialogue2_3","speaker":"Merry"},{"number":4,"text":"And because I received some good reviews… I can now officially debut as… an artist.","sourceKey":"Dialog:context:Wife53_FindDialogue2_4","speaker":"Merry"},{"number":5,"text":"Debut? That's great! Congratulations~","sourceKey":"Dialog:context:Wife53_FindDialogue2_5","speaker":"{playerName}"},{"number":6,"text":"It-it's a good thing indeed! But… but I need to be interviewed for my debut… Waaaah! Just thinking about facing that many people…","sourceKey":"Dialog:context:Wife53_FindDialogue2_6","speaker":"Merry"},{"number":7,"text":"The gallery side is worrying that I may make some mistakes… so they prepared the questions and answers in advance… It'll be fine if I memorize them all…","sourceKey":"Dialog:context:Wife53_FindDialogue2_7","speaker":"Merry"},{"number":8,"text":"Let me see… \"Q: Why did you start painting? A: Because I love it so I've been working hard.\"","sourceKey":"Dialog:context:Wife53_FindDialogue2_8","speaker":"{playerName}"},{"number":9,"text":"\"Q: How do you evaluate Master Rollin, who is in the same school of art as you? A: Her skill has always been my goal to strive for.\"","sourceKey":"Dialog:context:Wife53_FindDialogue2_9","speaker":"{playerName}"},{"number":10,"text":"\"Q: Will you hold a personal exhibition? A: No, no, my level is far from enough.\"","sourceKey":"Dialog:context:Wife53_FindDialogue2_10","speaker":"{playerName}"},{"number":11,"text":"Only three questions in total and they all seem pretty simple… All right, let me help you practice!","sourceKey":"Dialog:context:Wife53_FindDialogue2_11","speaker":"{playerName}"},{"number":12,"text":"After practicing with Merry for a while, the gallery manager takes her to the stage.","sourceKey":"Dialog:context:Wife53_FindDialogue2_12","speaker":null},{"number":13,"text":"The debut interview starts as scheduled, and the audience is packed with reporters and tourists.","sourceKey":"Dialog:context:Wife53_FindDialogue2_13","speaker":null},{"number":14,"text":"Today, another emerging colorist painter has announced to debut. Let's welcome Miss Merry Howard!","sourceKey":"Dialog:context:Wife53_FindDialogue2_14","speaker":"Host"},{"number":15,"text":"Eek—!","sourceKey":"Dialog:context:Wife53_FindDialogue2_15","speaker":"Merry"},{"number":16,"text":"(Merry… It looks like she's going to pass out. Can she really remember all those answers?)","sourceKey":"Dialog:context:Wife53_FindDialogue2_16","speaker":"{playerName}"},{"number":17,"text":"I believe everyone must have lots of questions to ask so let's start with the simple ones… Miss Merry, why did you start painting?","sourceKey":"Dialog:context:Wife53_FindDialogue2_17","speaker":"Host"},{"number":18,"text":"Ah… I-I… I like painting! So I've been working hard!","sourceKey":"Dialog:context:Wife53_FindDialogue2_18","speaker":"Merry"},{"number":19,"text":"(Wow, thank goodness!)","sourceKey":"Dialog:context:Wife53_FindDialogue2_19","speaker":"{playerName}"},{"number":20,"text":"Great answer! Then next question is… will you hold a personal exhibition in the future?","sourceKey":"Dialog:context:Wife53_FindDialogue2_20","speaker":"Host"},{"number":21,"text":"(Huh? The order of questions seems to have changed… But the content still remains the same… Merry should...)","sourceKey":"Dialog:context:Wife53_FindDialogue2_21","speaker":"{playerName}"},{"number":22,"text":"Ah… I… That's my goal to strive for!","sourceKey":"Dialog:context:Wife53_FindDialogue2_22","speaker":"Merry"},{"number":23,"text":"(—Merry! Listen to the question before answering! But it's okay. This answer can still work...)","sourceKey":"Dialog:context:Wife53_FindDialogue2_23","speaker":"{playerName}"},{"number":24,"text":"I didn't expect Miss Merry to have such great ambitions! So, the last question… How do you evaluate Master Rollin, who is in the same school of art as you?","sourceKey":"Dialog:context:Wife53_FindDialogue2_24","speaker":"Host"},{"number":25,"text":"Ah… Ah… Ah…","sourceKey":"Dialog:context:Wife53_FindDialogue2_25","speaker":"Merry"},{"number":26,"text":"…No, no, the level is far from enough!","sourceKey":"Dialog:context:Wife53_FindDialogue2_26","speaker":"Merry"},{"number":27,"text":"(...)","sourceKey":"Dialog:context:Wife53_FindDialogue2_27","speaker":"{playerName}"},{"number":28,"text":"The whole room fall silent for two seconds. Everyone is stunned for a while.","sourceKey":"Dialog:context:Wife53_FindDialogue2_28","speaker":null},{"number":29,"text":"…How-how arrogant she is… But this arrogance of genius is really admirable! We're looking forward to the day when Miss Merry surpasses the Master!","sourceKey":"Dialog:context:Wife53_FindDialogue2_29","speaker":"Host"},{"number":30,"text":"…Eh!? What did I say!!?","sourceKey":"Dialog:context:Wife53_FindDialogue2_30","speaker":"Merry"},{"number":31,"text":"Merry is muttering to herself in front of her painting.","sourceKey":"Dialog:context:Wife53_FindDialogue2_Text","speaker":null}]},{"id":"FindWife53_3","characterId":"wife_53","step":"3","lines":[{"number":1,"text":"Merry? What happened? Are you uncomfortable?","sourceKey":"Dialog:context:Wife53_FindDialogue3_1","speaker":"{playerName}"},{"number":2,"text":"Master Rollin… is here… She's viewing my paintings… I'm done for…","sourceKey":"Dialog:context:Wife53_FindDialogue3_2","speaker":"Merry"},{"number":3,"text":"Master Rollin is very strict… Even more experienced painters will get scolded by her… A newcomer like me… will be even worse…","sourceKey":"Dialog:context:Wife53_FindDialogue3_3","speaker":"Merry"},{"number":4,"text":"As you are talking, you notice a meticulous old woman viewing Merry's work.","sourceKey":"Dialog:context:Wife53_FindDialogue3_4","speaker":null},{"number":5,"text":"…Dull, too plain. Only learned the superficiality of the colorist painting, yet with no essence.","sourceKey":"Dialog:context:Wife53_FindDialogue3_5","speaker":"Rollin"},{"number":6,"text":"Exhibiting something like this… The public's understanding of colourist has declined recently.","sourceKey":"Dialog:context:Wife53_FindDialogue3_6","speaker":"Rollin"},{"number":7,"text":"(Woah… such a harsh criticism! This must be Master Rollin… What if Merry hear such comments…?)","sourceKey":"Dialog:context:Wife53_FindDialogue3_7","speaker":"{playerName}"},{"number":8,"text":"When you turn around, Merry, who was hiding in the corner just now, has disappeared suddenly.","sourceKey":"Dialog:context:Wife53_FindDialogue3_8","speaker":null},{"number":9,"text":"Merry—!?","sourceKey":"Dialog:context:Wife53_FindDialogue3_9","speaker":"{playerName}"},{"number":10,"text":"You calmly analyze Merry's smell while searching the exhibition hall and finally feel the familiar soft touch at the exit of the gallery.","sourceKey":"Dialog:context:Wife53_FindDialogue3_10","speaker":null},{"number":11,"text":"Merry…? Come out. It's okay now.","sourceKey":"Dialog:context:Wife53_FindDialogue3_11","speaker":"{playerName}"},{"number":12,"text":"I… I have distained the essence of the colourist… and even did some debut interview… I guess people like me can only hide in dark corner…","sourceKey":"Dialog:context:Wife53_FindDialogue3_12","speaker":"Merry"},{"number":13,"text":"Don't say that, Merry. Although what Master said is a bit harsh, your works are really loved by everyone.","sourceKey":"Dialog:context:Wife53_FindDialogue3_13","speaker":"{playerName}"},{"number":14,"text":"Creators often face criticism… Only by overcoming these setbacks can you create better works.","sourceKey":"Dialog:context:Wife53_FindDialogue3_14","speaker":"{playerName}"},{"number":15,"text":"And isn't Master Rollin the person Merry admires? It would be of great help to improve your skills after hearing her criticism.","sourceKey":"Dialog:context:Wife53_FindDialogue3_15","speaker":"{playerName}"},{"number":16,"text":"But I… I'm so scared… To face criticism and everything… I can't even communicate with people…","sourceKey":"Dialog:context:Wife53_FindDialogue3_16","speaker":"Merry"},{"number":17,"text":"But we've been communicating for a long time. You just need some time. Come on, opportunities like this are hard to come by.","sourceKey":"Dialog:context:Wife53_FindDialogue3_17","speaker":"{playerName}"},{"number":18,"text":"You hold Merry's hand and bring her to Rollin.","sourceKey":"Dialog:context:Wife53_FindDialogue3_18","speaker":null},{"number":19,"text":"What's wrong? Do you have something to tell me?","sourceKey":"Dialog:context:Wife53_FindDialogue3_19","speaker":"Rollin"},{"number":20,"text":"Roll… Master Rollin! I can't believe I'm really meeting you here… No, I'm sorry! For creating such a terrible work…","sourceKey":"Dialog:context:Wife53_FindDialogue3_20","speaker":"Merry"},{"number":21,"text":"What? You actually created this painting? Hmph… You're really young…","sourceKey":"Dialog:context:Wife53_FindDialogue3_21","speaker":"Rollin"},{"number":22,"text":"My-my skills are so poor! I'm sorry! But I hope to receive your guidance…","sourceKey":"Dialog:context:Wife53_FindDialogue3_22","speaker":"Merry"},{"number":23,"text":"So you've already heard my criticism? And you still have the nerve to come to me after creating such a painting?","sourceKey":"Dialog:context:Wife53_FindDialogue3_23","speaker":"Rollin"},{"number":24,"text":"Eek! I-I… you're right… Your criticism makes me feel… very ashamed… But… but I want to improve!","sourceKey":"Dialog:context:Wife53_FindDialogue3_24","speaker":"Merry"},{"number":25,"text":"Comparing to criticism… I'm more afraid of not being able to improve… I know it may sound shameless… but could you give me some guidance…?","sourceKey":"Dialog:context:Wife53_FindDialogue3_25","speaker":"Merry"},{"number":26,"text":"…","sourceKey":"Dialog:context:Wife53_FindDialogue3_26","speaker":"Rollin"},{"number":27,"text":"…There are too many problems. A word or two can't solve them all. Come to my atelier when you have time. I can teach you some experience and techniques.","sourceKey":"Dialog:context:Wife53_FindDialogue3_27","speaker":"Rollin"},{"number":28,"text":"Compared to those mediocre and cowardly painters, you're sort of talented. Keep working hard. Do not make my energy and time in vain.","sourceKey":"Dialog:context:Wife53_FindDialogue3_28","speaker":"Rollin"},{"number":29,"text":"Rollin hands over a business card after speaking and shakes hands formally with Merry then she bids farewell to you and leaves.","sourceKey":"Dialog:context:Wife53_FindDialogue3_29","speaker":null},{"number":30,"text":"This is great, Merry~ Now you can… Merry?","sourceKey":"Dialog:context:Wife53_FindDialogue3_30","speaker":"{playerName}"},{"number":31,"text":"…","sourceKey":"Dialog:context:Wife53_FindDialogue3_31","speaker":"Merry"},{"number":32,"text":"…It seems that this surprise is a bit too much for Merry. Let her digest it for a while~","sourceKey":"Dialog:context:Wife53_FindDialogue3_32","speaker":"{playerName}"},{"number":33,"text":"Merry is hiding in the corner, trembling.","sourceKey":"Dialog:context:Wife53_FindDialogue3_Text","speaker":"Merry"}]},{"id":"FindWife53_4","characterId":"wife_53","step":"4","lines":[{"number":1,"text":"I can't stand the anxiety of waiting for you every day. Please take me with you! We can rest together every day~","sourceKey":"Dialog:context:Wife53_FindDialogue4_1","speaker":null}]},{"id":"FindWife53_After","characterId":"wife_53","step":"After","lines":[{"number":1,"text":"Eek—! Why are so many people viewing my painting… I… I'm so nervous…!","sourceKey":"Dialog:context:Wife53_FindDialogueAfter_1","speaker":"Merry"}]},{"id":"FindWife54_1","characterId":"wife_54","step":"1","lines":[{"number":1,"text":"It's so lively here today. Is there a promotion going on?","sourceKey":"Dialog:context:Wife54_FindDialogue1_1","speaker":"{playerName}"},{"number":2,"text":"Today is the first day of the Magic Academy, and new students use the Magic Crystal Ball to determine their magic level. Our store has always provided this service.","sourceKey":"Dialog:context:Wife54_FindDialogue1_2","speaker":"Clerk"},{"number":3,"text":"You see many young children standing in line in front of a crystal ball. The person at the front of the line touches the ball with both hands, and the crystal ball immediately emits a faint light.","sourceKey":"Dialog:context:Wife54_FindDialogue1_3","speaker":null},{"number":4,"text":"(Hmm... so this is how to determine how much magical power you have?)","sourceKey":"Dialog:context:Wife54_FindDialogue1_4","speaker":"{playerName}"},{"number":5,"text":"The Magic Crystal Ball judges the aptitude of the person who touches it through the light it emits. The higher the magic level, the brighter it shines.","sourceKey":"Dialog:context:Wife54_FindDialogue1_5","speaker":"Erica"},{"number":6,"text":"(Ah, that's it...)","sourceKey":"Dialog:context:Wife54_FindDialogue1_6","speaker":"{playerName}"},{"number":7,"text":"The magic test proceeds in an orderly manner, all the way until it gets to a outrageously-dressed girl.","sourceKey":"Dialog:context:Wife54_FindDialogue1_7","speaker":null},{"number":8,"text":"Hehehe... The demonic hour is nigh, the powers of the material and the immaterial combine, and in the moment between infinity abides...","sourceKey":"Dialog:context:Wife54_FindDialogue1_8","speaker":"???"},{"number":9,"text":"(Huh? Is she reciting a spell? I can't understand a word...)","sourceKey":"Dialog:context:Wife54_FindDialogue1_9","speaker":"{playerName}"},{"number":10,"text":"Miss Ena, why are you here again? Today is the first day of school, and the store is very busy. Please don't cause any more trouble...","sourceKey":"Dialog:context:Wife54_FindDialogue1_10","speaker":"Clerk"},{"number":11,"text":"Enad'Num! Mortal, if the nomenclature is too obscure for you, the least you could do is address me by my title, the \"Infinite Eye\".","sourceKey":"Dialog:context:Wife54_FindDialogue1_11","speaker":"Ena"},{"number":12,"text":"Yes, yes, Your Majesty of the Infinite Eye... You've already been admitted to the school, then why waste money on this test? You must've taken on so many needless errands to afford these tests...","sourceKey":"Dialog:context:Wife54_FindDialogue1_12","speaker":"Clerk"},{"number":13,"text":"Mortals' understanding of the true essence of magic is so shallow! The codex has revealed to me that \"Reincarnation Day\" is nigh. My power shall increase tenfold this day!","sourceKey":"Dialog:context:Wife54_FindDialogue1_13","speaker":"Ena"},{"number":14,"text":"Mortals would normally never have to chance to beg an audience with the Infinite Eye, but just for today, Enad'Num shall grace your witless mortal eyes with this momentous display of full power... Hiya—!","sourceKey":"Dialog:context:Wife54_FindDialogue1_14","speaker":"Ena"},{"number":15,"text":"The girl incants loudly and solemnly places her hands on the crystal ball — but nothing happens.","sourceKey":"Dialog:context:Wife54_FindDialogue1_15","speaker":null},{"number":16,"text":"—!? How, how could this be! Enad'Num...","sourceKey":"Dialog:context:Wife54_FindDialogue1_16","speaker":"Ena"},{"number":17,"text":"Uh... what's all this?","sourceKey":"Dialog:context:Wife54_FindDialogue1_17","speaker":"{playerName}"},{"number":18,"text":"Sigh... This young lady was admitted to the Magic Academy last year. There's no need for her to assess her magic again, but she just won't listen...","sourceKey":"Dialog:context:Wife54_FindDialogue1_18","speaker":"Clerk"},{"number":19,"text":"Admitted? But the crystal ball didn't light up at all...","sourceKey":"Dialog:context:Wife54_FindDialogue1_19","speaker":"{playerName}"},{"number":20,"text":"Miss Ena scored full marks with her theoretical class, an unprecedented feat since the founding of the school. So the board decided to admit her despite her lack of magical ability...","sourceKey":"Dialog:context:Wife54_FindDialogue1_20","speaker":"Clerk"},{"number":21,"text":"Enad'Num, Enad'Num do not lack magic power! You... stop spreading false rumors at once! This, this is just... just that this crystal ball is broken! It is impossible to explore my fathomless magic power—!","sourceKey":"Dialog:context:Wife54_FindDialogue1_21","speaker":"Ena"},{"number":22,"text":"I saw everyone else's tests went pretty well... How about this, I have some magic power, so let me see if it's broken.","sourceKey":"Dialog:context:Wife54_FindDialogue1_22","speaker":"{playerName}"},{"number":23,"text":"A dazzling light bursts out of the crystal ball the moment your fingertips touch it, followed by an explosion as the ball explodes into beautiful fragments.","sourceKey":"Dialog:context:Wife54_FindDialogue1_23","speaker":null},{"number":24,"text":"...Ah... This, how much does this cost? I'll pay...","sourceKey":"Dialog:context:Wife54_FindDialogue1_24","speaker":"{playerName}"},{"number":25,"text":"...You... have such incredible magic power... Hahaha! You are the fated one that Enad'Num have been searching for thousands of years!","sourceKey":"Dialog:context:Wife54_FindDialogue1_25","speaker":"Ena"},{"number":26,"text":"If Enad'Num stay by your side, my magic power shall be greatly improved... Let's make a contract!","sourceKey":"Dialog:context:Wife54_FindDialogue1_26","speaker":"Ena"},{"number":27,"text":"Huh!? What, what!? I was just passing by!","sourceKey":"Dialog:context:Wife54_FindDialogue1_27","speaker":"{playerName}"},{"number":28,"text":"Please! If you don't want to make a contract, at least leave me your contact information! As an exchange, I can help you with theoretical knowledge~ It's a great deal!","sourceKey":"Dialog:context:Wife54_FindDialogue1_28","speaker":"Ena"},{"number":29,"text":"How, how did it come to this...","sourceKey":"Dialog:context:Wife54_FindDialogue1_29","speaker":"{playerName}"},{"number":30,"text":"The jewelry store is crowded with pupils.","sourceKey":"Dialog:context:Wife54_FindDialogue1_Text","speaker":null}]},{"id":"FindWife54_2","characterId":"wife_54","step":"2","lines":[{"number":1,"text":"Yo, fated one! Here to sign a contract with me? Hehehe, it's not too late to turn back now...","sourceKey":"Dialog:context:Wife54_FindDialogue2_1","speaker":"Ena"},{"number":2,"text":"Ena? You're so energetic today. Did your job go well?","sourceKey":"Dialog:context:Wife54_FindDialogue2_2","speaker":"{playerName}"},{"number":3,"text":"Don't you dare refer to me so casually. Watch and see! When the hour hand points to the hour mark, Enad'Num will transform into the strongest master of magic in the world!","sourceKey":"Dialog:context:Wife54_FindDialogue2_3","speaker":"Ena"},{"number":4,"text":"(Master of magic... doesn't Ena lack aptitude? Did she find a way to obtain magic power?)","sourceKey":"Dialog:context:Wife54_FindDialogue2_4","speaker":"{playerName}"},{"number":5,"text":"Everything comes from the Forbidden Technique, which is an ancient evil book that Enad'Num found in the restricted section...","sourceKey":"Dialog:context:Wife54_FindDialogue2_5","speaker":"Ena"},{"number":6,"text":"By mixing vampire blood, skeleton bone meal, and demonic tears, and painting the mixture in a complex magic circle, Enad'Num shall obtain eldritch powers when the sun is at its height!","sourceKey":"Dialog:context:Wife54_FindDialogue2_6","speaker":"Ena"},{"number":7,"text":"I didn't know such a thing existed... but it must be really complicated, preparing all these materials. Do you have enough time?","sourceKey":"Dialog:context:Wife54_FindDialogue2_7","speaker":"{playerName}"},{"number":8,"text":"Humph! What are you talking about? Everything is prepared! All that's left is the final step, and Enad'Num shall finally have the raw power of magic in my grasp!","sourceKey":"Dialog:context:Wife54_FindDialogue2_8","speaker":"Ena"},{"number":9,"text":"The time is... almost here! Come along, you! You shall be the first to witness my transformation into the master of magic!","sourceKey":"Dialog:context:Wife54_FindDialogue2_9","speaker":"Ena"},{"number":10,"text":"Ena happily takes your hand and hums a tune as she walks into the back alley.","sourceKey":"Dialog:context:Wife54_FindDialogue2_10","speaker":null},{"number":11,"text":"We're here! This is the most suitable place after my calculations! Last night, Enad'Num drew the magic circle here...","sourceKey":"Dialog:context:Wife54_FindDialogue2_11","speaker":"Ena"},{"number":12,"text":"...Now is the time. Enad'Num just need to step inside, and will be able to...","sourceKey":"Dialog:context:Wife54_FindDialogue2_12","speaker":"Ena"},{"number":13,"text":"Only some dark red streaks are visible where the magic circle should be, but the circle itself is nowhere to be found.","sourceKey":"Dialog:context:Wife54_FindDialogue2_13","speaker":null},{"number":14,"text":"Eh, eh, eh!? Where's my magic circle? I spent the whole night drawing it!!!","sourceKey":"Dialog:context:Wife54_FindDialogue2_14","speaker":"Ena"},{"number":15,"text":"Crying, Ena runs towards the incomplete magic circle, but when she gets closer, she screams and runs away.","sourceKey":"Dialog:context:Wife54_FindDialogue2_15","speaker":null},{"number":16,"text":"Ahhhhh!!!","sourceKey":"Dialog:context:Wife54_FindDialogue2_16","speaker":"Ena"},{"number":17,"text":"Ena!? What happened!?","sourceKey":"Dialog:context:Wife54_FindDialogue2_17","speaker":"{playerName}"},{"number":18,"text":"Bugs... so many bugs! It's so scary!","sourceKey":"Dialog:context:Wife54_FindDialogue2_18","speaker":"Ena"},{"number":19,"text":"When you rush over to take a look, you see many ants, beetles, and other insects crawling on the dark red marks left by the magic circle, and there is a sweet scent in the air.","sourceKey":"Dialog:context:Wife54_FindDialogue2_19","speaker":null},{"number":20,"text":"(Such a sweet scent. The bugs must have been attracted by it... but where did this scent come from? Could it be...)","sourceKey":"Dialog:context:Wife54_FindDialogue2_20","speaker":"{playerName}"},{"number":21,"text":"...Ena, did you really prepare the materials for the magic circle according to the book?","sourceKey":"Dialog:context:Wife54_FindDialogue2_21","speaker":"{playerName}"},{"number":22,"text":"*Sob*... the final product's color is exactly the same as the one in the book! It took me all night to mix!","sourceKey":"Dialog:context:Wife54_FindDialogue2_22","speaker":"Ena"},{"number":23,"text":"Just having the same color won't work... Did you use vampire blood?","sourceKey":"Dialog:context:Wife54_FindDialogue2_23","speaker":"{playerName}"},{"number":24,"text":"I... used strawberry jam instead...","sourceKey":"Dialog:context:Wife54_FindDialogue2_24","speaker":"Ena"},{"number":25,"text":"Then what about the bone powder...","sourceKey":"Dialog:context:Wife54_FindDialogue2_25","speaker":"{playerName}"},{"number":26,"text":"Took a bag of sugar from home...","sourceKey":"Dialog:context:Wife54_FindDialogue2_26","speaker":"Ena"},{"number":27,"text":"Demon tears...","sourceKey":"Dialog:context:Wife54_FindDialogue2_27","speaker":"{playerName}"},{"number":28,"text":"Chocolate sauce... The—those ingredients are so rare, and they go for outrageous prices on the black market... I... I can't  get enough money!","sourceKey":"Dialog:context:Wife54_FindDialogue2_28","speaker":"Ena"},{"number":29,"text":"Then of course the magic circle won't work!","sourceKey":"Dialog:context:Wife54_FindDialogue2_29","speaker":"{playerName}"},{"number":30,"text":"Ena is waiting for you excitedly.","sourceKey":"Dialog:context:Wife54_FindDialogue2_Text","speaker":null}]},{"id":"FindWife54_3","characterId":"wife_54","step":"3","lines":[{"number":1,"text":"Yo, fated one! Here to sign a contract with me? Hehehe, it's not too late to turn back now...","sourceKey":"Dialog:context:Wife54_FindDialogue3_1","speaker":"Ena"},{"number":2,"text":"Ena? You're so energetic today. Did your job go well?","sourceKey":"Dialog:context:Wife54_FindDialogue3_2","speaker":"{playerName}"},{"number":3,"text":"Don't feign familiarity with such casual appellations! Don't even blink! When the power of the demon god descends, Enad'Num will become the strongest master of magic in the world!","sourceKey":"Dialog:context:Wife54_FindDialogue3_3","speaker":"Ena"},{"number":4,"text":"I feel like we've had a similar conversation before... Did you find another way?","sourceKey":"Dialog:context:Wife54_FindDialogue3_4","speaker":"{playerName}"},{"number":5,"text":"Of course! Enad'Num don't give up easily! Enad'Num searched all the forbidden books and finally found a new method!","sourceKey":"Dialog:context:Wife54_FindDialogue3_5","speaker":"Ena"},{"number":6,"text":"Wow, that's really impressive... You're indeed a special admission with full marks in theory...","sourceKey":"Dialog:context:Wife54_FindDialogue3_6","speaker":"{playerName}"},{"number":7,"text":"And it's even simpler than last time! Just put the \"orange creature\" into a specific magic circle, and the power of the demon god shall be mine!","sourceKey":"Dialog:context:Wife54_FindDialogue3_7","speaker":"Ena"},{"number":8,"text":"Demon god... It sounds very ancient... Wait, you said orange... Surely you don't mean me, Ena?","sourceKey":"Dialog:context:Wife54_FindDialogue3_8","speaker":"{playerName}"},{"number":9,"text":"Hehehe... Are you scared? Not to worry! You just need to be a witness to this ceremony. Enad'Num have found the perfect substitute!","sourceKey":"Dialog:context:Wife54_FindDialogue3_9","speaker":"Ena"},{"number":10,"text":"You notice that Ena is holding a small bucket with clear water and a small orange fish inside.","sourceKey":"Dialog:context:Wife54_FindDialogue3_10","speaker":null},{"number":11,"text":"Oh, a little fish with a rare pattern on it~","sourceKey":"Dialog:context:Wife54_FindDialogue3_11","speaker":"{playerName}"},{"number":12,"text":"Hmph! It took me a long time to find this fish! As long as Enad'Num finish drawing the rest of the magic circle, the ritual can begin immediately!","sourceKey":"Dialog:context:Wife54_FindDialogue3_12","speaker":"Ena"},{"number":13,"text":"However, modern magic knowledge alone cannot comprehend such a complex spell, and Enad'Num is not sure about the specific effects of the magic circle. There is no record in the books...","sourceKey":"Dialog:context:Wife54_FindDialogue3_13","speaker":"Ena"},{"number":14,"text":"But the risk is necessary. Only by facing fear can we earn the right to meet the demon god... O finned creature in the water! Be prepared to contribute to our great cause!","sourceKey":"Dialog:context:Wife54_FindDialogue3_14","speaker":"Ena"},{"number":15,"text":"Ena draws the magic circle eagerly, but as it takes shape, she looks more and more hesitant.","sourceKey":"Dialog:context:Wife54_FindDialogue3_15","speaker":null},{"number":16,"text":"This, this pattern... The extension looks so dangerous... Could this be the Sacrificial Rite, long labeled as black magic?","sourceKey":"Dialog:context:Wife54_FindDialogue3_16","speaker":"Ena"},{"number":17,"text":"If, if that's the case... the fishy will... No, it can't be! It's just speculation. You'll be fine. Rest easy, creature!","sourceKey":"Dialog:context:Wife54_FindDialogue3_17","speaker":"Ena"},{"number":18,"text":"Only through courage and a dance with fate can Enad'Num attain the power of the demon god!","sourceKey":"Dialog:context:Wife54_FindDialogue3_18","speaker":"Ena"},{"number":19,"text":"Enad'Num! You are going to become the master of magic! Show your courage! It's just a fish...","sourceKey":"Dialog:context:Wife54_FindDialogue3_19","speaker":"Ena"},{"number":20,"text":"Ugh... Ugh... Damn it—! I, I...","sourceKey":"Dialog:context:Wife54_FindDialogue3_20","speaker":"Ena"},{"number":21,"text":"Ena? Are you okay...?","sourceKey":"Dialog:context:Wife54_FindDialogue3_21","speaker":"{playerName}"},{"number":22,"text":"...Waaaah—! I can't do it--! Sorry, little fish!","sourceKey":"Dialog:context:Wife54_FindDialogue3_22","speaker":"Ena"},{"number":23,"text":"Enad'Num took advantage of you because of your scaly littleness, and Enad'Num almost put you in danger...! Enad'Num is not worthy!","sourceKey":"Dialog:context:Wife54_FindDialogue3_23","speaker":"Ena"},{"number":24,"text":"(...Just as I thought~)","sourceKey":"Dialog:context:Wife54_FindDialogue3_24","speaker":"{playerName}"},{"number":25,"text":"All's well that ends well. You stopped yourself in time, and the little fish isn't hurt.","sourceKey":"Dialog:context:Wife54_FindDialogue3_25","speaker":"{playerName}"},{"number":26,"text":"As for magic... I think a true magician does not need to rely on the power of a \"demon\". Even if you gain magic power, it wouldn't be your own.","sourceKey":"Dialog:context:Wife54_FindDialogue3_26","speaker":"{playerName}"},{"number":27,"text":"*Sob*... You... You're right! Enad'Num won't rely on any demon! Someday, Enad'Num will become a magician on my own!","sourceKey":"Dialog:context:Wife54_FindDialogue3_27","speaker":"Ena"},{"number":28,"text":"The little fish's family must miss it too... O fated one! Let's release this creature together!","sourceKey":"Dialog:context:Wife54_FindDialogue3_28","speaker":"Ena"},{"number":29,"text":"Ena is waiting for you excitedly.","sourceKey":"Dialog:context:Wife54_FindDialogue3_Text","speaker":null}]},{"id":"FindWife54_4","characterId":"wife_54","step":"4","lines":[{"number":1,"text":"...Ena, how are you going to gain magic power this time?","sourceKey":"Dialog:context:Wife54_FindDialogue4_1","speaker":"{playerName}"},{"number":2,"text":"Hmph! Enad'Num have come to report good news to you! Enad'Num have lit up the magic crystal ball!","sourceKey":"Dialog:context:Wife54_FindDialogue4_2","speaker":"Ena"},{"number":3,"text":"Huh? The magic crystal ball is lit? Does that mean you've finally attained magic power?","sourceKey":"Dialog:context:Wife54_FindDialogue4_3","speaker":"{playerName}"},{"number":4,"text":"Yes! Though Enad'Num have spent all our savings...but these sacrifices are worth it in order to gain magic power!","sourceKey":"Dialog:context:Wife54_FindDialogue4_4","speaker":"Ena"},{"number":5,"text":"Let me show you! Servant, take this money and take me to be crowned as king!","sourceKey":"Dialog:context:Wife54_FindDialogue4_5","speaker":"Ena"},{"number":6,"text":"As Ena requested, the jewelry store clerk takes her to the magic crystal ball again...","sourceKey":"Dialog:context:Wife54_FindDialogue4_6","speaker":null},{"number":7,"text":"...However, the result this time is no different. No matter how Ena touches it, the crystal ball does not emit any light.","sourceKey":"Dialog:context:Wife54_FindDialogue4_7","speaker":null},{"number":8,"text":"Why!? I easily lit it up at the Magic Gathering! There must be a problem with this crystal ball!","sourceKey":"Dialog:context:Wife54_FindDialogue4_8","speaker":"Ena"},{"number":9,"text":"Magic Gathering? What is that?","sourceKey":"Dialog:context:Wife54_FindDialogue4_9","speaker":"{playerName}"},{"number":10,"text":"It is a gathering established by a powerful old mage, dedicated to helping everyone learn magic! What he teaches is not found in any book at school!","sourceKey":"Dialog:context:Wife54_FindDialogue4_10","speaker":"Ena"},{"number":11,"text":"It was originally a secret forbidden technique that he taught me at a special price because of my excellent aptitude... but why won't this ball glow?!","sourceKey":"Dialog:context:Wife54_FindDialogue4_11","speaker":"Ena"},{"number":12,"text":"(It doesn't sound like a reliable organization... Could Ena have been scammed?)","sourceKey":"Dialog:context:Wife54_FindDialogue4_12","speaker":"{playerName}"},{"number":13,"text":"...Ena, don't worry, can you take me to that Magic Gathering?","sourceKey":"Dialog:context:Wife54_FindDialogue4_13","speaker":"{playerName}"},{"number":14,"text":"Okay... Okay! Great, you can come with me and witness my powerful magic! Enad'Num have definitely got it this time!","sourceKey":"Dialog:context:Wife54_FindDialogue4_14","speaker":"Ena"},{"number":15,"text":"You follow Ena to a dead-end alleyway in Drakenberg and see the so-called Magic Gathering.","sourceKey":"Dialog:context:Wife54_FindDialogue4_15","speaker":null},{"number":16,"text":"A group of people surround a ball emiting strange light. Although the residents here may not be familiar with this particular item, you recognize it at a glance.","sourceKey":"Dialog:context:Wife54_FindDialogue4_16","speaker":null},{"number":17,"text":"Look, look! The master has led another group of people to light up the crystal ball! It can't be anything else...","sourceKey":"Dialog:context:Wife54_FindDialogue4_17","speaker":"Ena"},{"number":18,"text":"This might come as a blow... but that's just a light bulb, Ena. You click a button to turn it on or off, no magic required.","sourceKey":"Dialog:context:Wife54_FindDialogue4_18","speaker":"{playerName}"},{"number":19,"text":"You... what are you talking about!? What light bulb? How could this be fake... I spent whole life savings on it!","sourceKey":"Dialog:context:Wife54_FindDialogue4_19","speaker":"Ena"},{"number":20,"text":"(I knew it, this so-called magic gathering is just a scam! We need to expose them!)","sourceKey":"Dialog:context:Wife54_FindDialogue4_20","speaker":"{playerName}"},{"number":21,"text":"You angrily walk forward and snatch the so-called crystal ball, smashing it to pieces. The light bulb and connectors inside are exposed for everyone to see.","sourceKey":"Dialog:context:Wife54_FindDialogue4_21","speaker":null},{"number":22,"text":"In the midst of the shock, the \"old mage\" caught in the act makes a run for it.","sourceKey":"Dialog:context:Wife54_FindDialogue4_22","speaker":null},{"number":23,"text":"Stop right there, you old fraud! Ena, let's get after him and get our money back...","sourceKey":"Dialog:context:Wife54_FindDialogue4_23","speaker":"{playerName}"},{"number":24,"text":"It... it's alright.","sourceKey":"Dialog:context:Wife54_FindDialogue4_24","speaker":"Ena"},{"number":25,"text":"This time, Ena is not angry. She just silently sheds tears and starts removing the exaggerated decorations from her body.","sourceKey":"Dialog:context:Wife54_FindDialogue4_25","speaker":null},{"number":26,"text":"Ena...?","sourceKey":"Dialog:context:Wife54_FindDialogue4_26","speaker":"{playerName}"},{"number":27,"text":"It's all my fault... I have been holding onto all these unrealistic fantasies… I'm sorry, {playerName}, for troubling you all this time...","sourceKey":"Dialog:context:Wife54_FindDialogue4_27","speaker":"Ena"},{"number":28,"text":"No matter how extravagantly I dress, or how pretentiously I speak... it doesn't change the facts! I don't have magic! I can't ever learn magic!","sourceKey":"Dialog:context:Wife54_FindDialogue4_28","speaker":"Ena"},{"number":29,"text":"In the end, Ena runs away in tears. You want to catch up with her, but you can no longer recognize her figure in the crowd.","sourceKey":"Dialog:context:Wife54_FindDialogue4_29","speaker":null},{"number":30,"text":"Ena is waiting for you excitedly.","sourceKey":"Dialog:context:Wife54_FindDialogue4_Text","speaker":null}]},{"id":"FindWife54_5","characterId":"wife_54","step":"5","lines":[{"number":1,"text":"(It's so lively here today, is it new intake for the Magic Academy again? Say, where's Ena...)","sourceKey":"Dialog:context:Wife54_FindDialogue5_1","speaker":"{playerName}"},{"number":2,"text":"Next to the magic crystal ball, you see Ena, dressed in plain clothes, talking theory with the new students.","sourceKey":"Dialog:context:Wife54_FindDialogue5_2","speaker":null},{"number":3,"text":"Wow! Are you the genius student who got full marks in all subjects in the academy!? Can I also become a powerful mage like you?","sourceKey":"Dialog:context:Wife54_FindDialogue5_3","speaker":"Freshman"},{"number":4,"text":"...","sourceKey":"Dialog:context:Wife54_FindDialogue5_4","speaker":"Ena"},{"number":5,"text":"...Well, you will definitely become very powerful...but it's better not to be like me~ Ahaha~ Come on, let's test your magic power.","sourceKey":"Dialog:context:Wife54_FindDialogue5_5","speaker":"Ena"},{"number":6,"text":"The crystal ball emits a dazzling light as Ena blesses the joyful newcomers, but her eyes are filled with envy and sadness.","sourceKey":"Dialog:context:Wife54_FindDialogue5_6","speaker":null},{"number":7,"text":"...Ena? Are you okay?","sourceKey":"Dialog:context:Wife54_FindDialogue5_7","speaker":"{playerName}"},{"number":8,"text":"{playerName}? Hey, I… I'm fine. I'm just here to guide the new students as an outstanding student from the Magic Academy.","sourceKey":"Dialog:context:Wife54_FindDialogue5_8","speaker":"Ena"},{"number":9,"text":"Is this part of your job?","sourceKey":"Dialog:context:Wife54_FindDialogue5_9","speaker":"{playerName}"},{"number":10,"text":"No... I volunteered for this. My immature actions caused a lot of trouble for this shop before, so I wanted to do something to make up for it.","sourceKey":"Dialog:context:Wife54_FindDialogue5_10","speaker":"Ena"},{"number":11,"text":"On one hand, these children are promising newcomers who need proper guidance...","sourceKey":"Dialog:context:Wife54_FindDialogue5_11","speaker":"Ena"},{"number":12,"text":"And on the other hand... seeing their talent helps me dispel those unrealistic thoughts.","sourceKey":"Dialog:context:Wife54_FindDialogue5_12","speaker":"Ena"},{"number":13,"text":"(Ena has sacrificed so much to gain magic power, but she still has nothing to show for it... her expression is really hard to watch.)","sourceKey":"Dialog:context:Wife54_FindDialogue5_13","speaker":"{playerName}"},{"number":14,"text":"(Is talent really all that counts? She's a genius with perfect scores in all subjects, but just because she doesn't have magic power...!)","sourceKey":"Dialog:context:Wife54_FindDialogue5_14","speaker":"{playerName}"},{"number":15,"text":"(If magic won't answer her wishes... then I will!)","sourceKey":"Dialog:context:Wife54_FindDialogue5_15","speaker":"{playerName}"},{"number":16,"text":"...Hahaha... it seems you've fallen into the realm of mortals, Your Majesty of the Infinite Eye.","sourceKey":"Dialog:context:Wife54_FindDialogue5_16","speaker":"{playerName}"},{"number":17,"text":"{playerName}? W-What's wrong? Don't suddenly call me by that name...","sourceKey":"Dialog:context:Wife54_FindDialogue5_17","speaker":"Ena"},{"number":18,"text":"Why not? Mortals would do well to heed the title of Master of Magic!","sourceKey":"Dialog:context:Wife54_FindDialogue5_18","speaker":"{playerName}"},{"number":19,"text":"That's enough... don't mention that name again! You should know that I don't have any magic power! How can I use magic?!","sourceKey":"Dialog:context:Wife54_FindDialogue5_19","speaker":"Ena"},{"number":20,"text":"So what?","sourceKey":"Dialog:context:Wife54_FindDialogue5_20","speaker":"{playerName}"},{"number":21,"text":"As you speak, you touch the magic crystal ball holding Ena's hand.","sourceKey":"Dialog:context:Wife54_FindDialogue5_21","speaker":null},{"number":22,"text":"Finally, as you and Ena touch the crystal ball together, it begins to give off a gentle yet powerful light.","sourceKey":"Dialog:context:Wife54_FindDialogue5_22","speaker":null},{"number":23,"text":"Huh...?","sourceKey":"Dialog:context:Wife54_FindDialogue5_23","speaker":"Ena"},{"number":24,"text":"How could the Master of Magic be expected to give of her own power like this... Come, my \"fated one\"!","sourceKey":"Dialog:context:Wife54_FindDialogue5_24","speaker":"{playerName}"},{"number":25,"text":"Let us bind ourselves here and now, and allow me to pledge all the magic power in this body to you!","sourceKey":"Dialog:context:Wife54_FindDialogue5_25","speaker":"{playerName}"},{"number":26,"text":"With your depthless intellect and boundless wisdom, we shall become \"Masters of Magic\", two in one!","sourceKey":"Dialog:context:Wife54_FindDialogue5_26","speaker":"{playerName}"},{"number":27,"text":"Your Majesty the Infinite Eye! Remember your name!","sourceKey":"Dialog:context:Wife54_FindDialogue5_27","speaker":"{playerName}"},{"number":28,"text":"{playerName}...","sourceKey":"Dialog:context:Wife54_FindDialogue5_28","speaker":"Ena"},{"number":29,"text":"...Hehehe... It would not do for me to turn down such a sincere invitation. Enad'Num heed your call!","sourceKey":"Dialog:context:Wife54_FindDialogue5_29","speaker":"Ena"},{"number":30,"text":"The contract has now been sealed! Whatever future this Infinite Eye sees, you and Enad'Num shall witness together!","sourceKey":"Dialog:context:Wife54_FindDialogue5_30","speaker":"Ena"},{"number":31,"text":"The jewelry store is crowded with pupils.","sourceKey":"Dialog:context:Wife54_FindDialogue5_Text","speaker":null}]},{"id":"FindWife54_After","characterId":"wife_54","step":"After","lines":[{"number":1,"text":"Ah! My head… The memories of past life is surging into my mind…!","sourceKey":"Dialog:context:Wife54_FindDialogueAfter_1","speaker":"Ena"}]},{"id":"FindWife55_1","characterId":"wife_55","step":"1","lines":[{"number":1,"text":"Her Royal Highness, Princess, please return as soon as possible...","sourceKey":"Dialog:context:Wife55_FindDialogue1_1","speaker":"Soldier"},{"number":2,"text":"No matter what means you use! This princess will never surrender!","sourceKey":"Dialog:context:Wife55_FindDialogue1_2","speaker":"Unfamous princess"},{"number":3,"text":"Umm, is this a princess? A real princess?!","sourceKey":"Dialog:context:Wife55_FindDialogue1_3","speaker":"{playerName}"},{"number":4,"text":"You and the guard inquired and learned that the princess' name is Lulu, the only daughter of the neighboring country’s royal family.","sourceKey":"Dialog:context:Wife55_FindDialogue1_4","speaker":null},{"number":5,"text":"The neighboring country was once a barren land. To improve the lives of its people, the royal family spent a lot of wealth.","sourceKey":"Dialog:context:Wife55_FindDialogue1_5","speaker":null},{"number":6,"text":"This wealth included a large amount of money borrowed from Drakenberg. Although the royal family did improve the lives of their country’s people, it could not repay the debt on time.","sourceKey":"Dialog:context:Wife55_FindDialogue1_6","speaker":null},{"number":7,"text":"To fulfill their duty, they decided to detain the princess here.","sourceKey":"Dialog:context:Wife55_FindDialogue1_7","speaker":null},{"number":8,"text":"We had no intention of detaining the princess. To be honest, we don't know what to do with her....","sourceKey":"Dialog:context:Wife55_FindDialogue1_8","speaker":"Soldier"},{"number":9,"text":"Can she be considered a hostage? Then, what about the food in her hands?","sourceKey":"Dialog:context:Wife55_FindDialogue1_9","speaker":"{playerName}"},{"number":10,"text":"Ah, it was given by passersby because she looks cute~","sourceKey":"Dialog:context:Wife55_FindDialogue1_10","speaker":"Soldier"},{"number":11,"text":"Oh my...","sourceKey":"Dialog:context:Wife55_FindDialogue1_11","speaker":"{playerName}"},{"number":12,"text":"You approach the princess. Although the people of Drakenberg don’t mean to make her feel restricted, she feels kidnapped.","sourceKey":"Dialog:context:Wife55_FindDialogue1_12","speaker":null},{"number":13,"text":"Humph, do you want to trick me? I won’t speak!","sourceKey":"Dialog:context:Wife55_FindDialogue1_13","speaker":"Lulu"},{"number":14,"text":"Try your best, go ahead!","sourceKey":"Dialog:context:Wife55_FindDialogue1_14","speaker":"Lulu"},{"number":15,"text":"After seeing the princess eating a bunch of fried food, you go buy her a can of cold cola.","sourceKey":"Dialog:context:Wife55_FindDialogue1_15","speaker":null},{"number":16,"text":"Huh... What is that...?","sourceKey":"Dialog:context:Wife55_FindDialogue1_16","speaker":"Lulu"},{"number":17,"text":"You open the can and pour the refreshing soda into your mouth in front of the princess.","sourceKey":"Dialog:context:Wife55_FindDialogue1_17","speaker":null},{"number":18,"text":"Phew, how refreshing!","sourceKey":"Dialog:context:Wife55_FindDialogue1_18","speaker":"{playerName}"},{"number":19,"text":"Hmm... So tricky! After eating this food, I’m super thirsty!","sourceKey":"Dialog:context:Wife55_FindDialogue1_19","speaker":"Lulu"},{"number":20,"text":"But, how can a princess be tempted by such things?!","sourceKey":"Dialog:context:Wife55_FindDialogue1_20","speaker":"Lulu"},{"number":21,"text":"Having said this, the princess raises her head proudly, staying like this for three minutes!","sourceKey":"Dialog:context:Wife55_FindDialogue1_21","speaker":null},{"number":22,"text":"Finally, holding the can of soda with a satisfied smile, she tells you and the guard exactly the same thing she said before.","sourceKey":"Dialog:context:Wife55_FindDialogue1_22","speaker":null},{"number":23,"text":"Round one—The princess is defeated!","sourceKey":"Dialog:context:Wife55_FindDialogue1_23","speaker":null},{"number":24,"text":"The princess seats by the shore with shackles on.","sourceKey":"Dialog:context:Wife55_FindDialogue1_Text","speaker":null}]},{"id":"FindWife55_2","characterId":"wife_55","step":"2","lines":[{"number":1,"text":"It's you! The one who embarrassed me last time! Your name is {playerName}, right? I will never forget this grudge... Though, do you have any cola with you now?","sourceKey":"Dialog:context:Wife55_FindDialogue2_1","speaker":"Lulu"}]},{"id":"FindWife55_3","characterId":"wife_55","step":"3","lines":[{"number":1,"text":"Next time I will definitely not let you see me lose my composure again!","sourceKey":"Dialog:context:Wife55_FindDialogue3_1","speaker":"Lulu"}]},{"id":"FindWife55_4","characterId":"wife_55","step":"4","lines":[{"number":1,"text":"Humph, we meet again... You are giving me a chance to take revenge!","sourceKey":"Dialog:context:Wife55_FindDialogue4_1","speaker":"Lulu"},{"number":2,"text":"Oh, hello princess.","sourceKey":"Dialog:context:Wife55_FindDialogue4_2","speaker":"{playerName}"},{"number":3,"text":"Hello... No no, it's you! The one who made me lose face last time!","sourceKey":"Dialog:context:Wife55_FindDialogue4_3","speaker":"Lulu"},{"number":4,"text":"Come on! I won’t make the same mistake this time—I’ve eaten enough and am not thirsty!","sourceKey":"Dialog:context:Wife55_FindDialogue4_4","speaker":"Lulu"},{"number":5,"text":"Bring it on! I won't say a word! I will let Drakenberg witness my victory and tenacity!","sourceKey":"Dialog:context:Wife55_FindDialogue4_5","speaker":"Lulu"},{"number":6,"text":"(Can this be considered heroic...?)","sourceKey":"Dialog:context:Wife55_FindDialogue4_6","speaker":"{playerName}"},{"number":7,"text":"Seeing the fierce princess, you decide to stay and have some fun with her.","sourceKey":"Dialog:context:Wife55_FindDialogue4_7","speaker":null},{"number":8,"text":"Considering the princess has already eaten enough, you turn your eyes and go to a nearby dessert shop to buy her a small and exquisite chocolate cake.","sourceKey":"Dialog:context:Wife55_FindDialogue4_8","speaker":null},{"number":9,"text":"Ahh—! This, this is—!","sourceKey":"Dialog:context:Wife55_FindDialogue4_9","speaker":"Lulu"},{"number":10,"text":"Your Highness~ Does your stomach have space for a dessert?","sourceKey":"Dialog:context:Wife55_FindDialogue4_10","speaker":"{playerName}"},{"number":11,"text":"Aah! How despicable~!","sourceKey":"Dialog:context:Wife55_FindDialogue4_11","speaker":"Lulu"},{"number":12,"text":"This is the hot-selling and limited dessert in Drakenberg. Each person can only buy one. If Your Highness don't eat it, I'll have to eat it myself.","sourceKey":"Dialog:context:Wife55_FindDialogue4_12","speaker":"{playerName}"},{"number":13,"text":"Damn you... I-I am a princess! This kind of temptation does nothing to me! Don't underestimate me!","sourceKey":"Dialog:context:Wife55_FindDialogue4_13","speaker":"Lulu"},{"number":14,"text":"And so, the princess lifts her head proudly and stays like this for a full minute!","sourceKey":"Dialog:context:Wife55_FindDialogue4_14","speaker":null},{"number":15,"text":"Finally, she takes a bite of the sweet, delicious chocolate cake and later tells you about her birthday smiling happily.","sourceKey":"Dialog:context:Wife55_FindDialogue4_15","speaker":null},{"number":16,"text":"Second round—Princess, you lost! All because of that special cake!","sourceKey":"Dialog:context:Wife55_FindDialogue4_16","speaker":null},{"number":17,"text":"The princess confidently beckons you over.","sourceKey":"Dialog:context:Wife55_FindDialogue4_Text","speaker":null}]},{"id":"FindWife55_5","characterId":"wife_55","step":"5","lines":[{"number":1,"text":"I wonder how my father and mother are doing... I’m not homesick! I’m fulfilling my duty by staying in Drakensberg as collateral for our debt!","sourceKey":"Dialog:context:Wife55_FindDialogue5_1","speaker":"Lulu"}]},{"id":"FindWife55_6","characterId":"wife_55","step":"6","lines":[{"number":1,"text":"The people here are fortunate to have been born on fertile land... But don't be too proud! Our people will not lose to you! They will definitely be happier!","sourceKey":"Dialog:context:Wife55_FindDialogue6_1","speaker":"Lulu"}]},{"id":"FindWife55_7","characterId":"wife_55","step":"7","lines":[{"number":1,"text":"I think the way you do things is brilliant. Do you want to come to my country to govern? You’ll definitely achieve great things!","sourceKey":"Dialog:context:Wife55_FindDialogue7_1","speaker":"Lulu"}]},{"id":"FindWife55_8","characterId":"wife_55","step":"8","lines":[{"number":1,"text":"You're here again! Fellow who has made me reveal so much information... I will always remember your name!","sourceKey":"Dialog:context:Wife55_FindDialogue8_1","speaker":"Lulu"},{"number":2,"text":"But this time, you won't succeed! Your food temptations no longer work on me!","sourceKey":"Dialog:context:Wife55_FindDialogue8_2","speaker":"Lulu"},{"number":3,"text":"The princess looks confident. Maybe using food to persuade her won’t work anymore.","sourceKey":"Dialog:context:Wife55_FindDialogue8_3","speaker":null},{"number":4,"text":"So, what should you do to win this difficult battle?","sourceKey":"Dialog:context:Wife55_FindDialogue8_4","speaker":null},{"number":5,"text":"While pondering, you figure out an idea.","sourceKey":"Dialog:context:Wife55_FindDialogue8_5","speaker":null},{"number":6,"text":"Your Highness, let me tell you a story.","sourceKey":"Dialog:context:Wife55_FindDialogue8_6","speaker":"{playerName}"},{"number":7,"text":"Huh? Aren't you here to pry information? I don't know what you're thinking, but okay! I will listen to what you have to say!","sourceKey":"Dialog:context:Wife55_FindDialogue8_7","speaker":"Lulu"},{"number":8,"text":"Swimming in your memory, you tell the princess the story of your favorite comic when you were in the world you come from.","sourceKey":"Dialog:context:Wife55_FindDialogue8_8","speaker":null},{"number":9,"text":"As you tell the story, the princess becomes more and more fascinated while her eyes shine brightly.","sourceKey":"Dialog:context:Wife55_FindDialogue8_9","speaker":null},{"number":10,"text":"Soon, the story reaches its climax—","sourceKey":"Dialog:context:Wife55_FindDialogue8_10","speaker":null},{"number":11,"text":"... And so, the young man stood up once again, using all his strength to throw his final punch—","sourceKey":"Dialog:context:Wife55_FindDialogue8_11","speaker":"{playerName}"},{"number":12,"text":"Ohhhh!","sourceKey":"Dialog:context:Wife55_FindDialogue8_12","speaker":"Lulu"},{"number":13,"text":"......","sourceKey":"Dialog:context:Wife55_FindDialogue8_13","speaker":"{playerName}"},{"number":14,"text":"And then? What happened next? Quickly tell me the result!","sourceKey":"Dialog:context:Wife55_FindDialogue8_14","speaker":"Lulu"},{"number":15,"text":"Seeing the excited princess, you show a victorious expression.","sourceKey":"Dialog:context:Wife55_FindDialogue8_15","speaker":null},{"number":16,"text":"Ah... Ah! Is this part of the test...? No, no! I don't want it, I don't want it!","sourceKey":"Dialog:context:Wife55_FindDialogue8_16","speaker":"Lulu"},{"number":17,"text":"Tell me the end of the story! Quickly tell me—! I really want to hear it—!","sourceKey":"Dialog:context:Wife55_FindDialogue8_17","speaker":"Lulu"},{"number":18,"text":"And so, the princess's proud head soon lowered!","sourceKey":"Dialog:context:Wife55_FindDialogue8_18","speaker":null},{"number":19,"text":"Finally, the princess listens to the story’s perfect ending. Then, she tells you about her cat, revealing her beautiful smile.","sourceKey":"Dialog:context:Wife55_FindDialogue8_19","speaker":null},{"number":20,"text":"Third round—Your Highness the Princess has been defeated! The power of comics is terrifying!","sourceKey":"Dialog:context:Wife55_FindDialogue8_20","speaker":null},{"number":21,"text":"The princess greets you with great confidence.","sourceKey":"Dialog:context:Wife55_FindDialogue8_Text","speaker":null}]},{"id":"FindWife55_9","characterId":"wife_55","step":"9","lines":[{"number":1,"text":"Rude! How come you don’t greet the princess as she deserves? Okay, let's not talk about it for now. Anyway, come and chat with me!","sourceKey":"Dialog:context:Wife55_FindDialogue9_1","speaker":"Lulu"}]},{"id":"FindWife55_10","characterId":"wife_55","step":"10","lines":[{"number":1,"text":"No matter how messy the situation is, I will always be a noble princess! Unlike you, the commoners... Oops, I’m sorry! My father has told me not to look down on others...","sourceKey":"Dialog:context:Wife55_FindDialogue10_1","speaker":"Lulu"}]},{"id":"FindWife55_11","characterId":"wife_55","step":"11","lines":[{"number":1,"text":"Can you do needlework? Can you help this princess mend her clothes? The guards? They're still working, it's not good to disturb them...","sourceKey":"Dialog:context:Wife55_FindDialogue11_1","speaker":"Lulu"}]},{"id":"FindWife55_12","characterId":"wife_55","step":"12","lines":[{"number":1,"text":"Damn it, I must take revenge for the last time!","sourceKey":"Dialog:context:Wife55_FindDialogue12_1","speaker":"Lulu"},{"number":2,"text":"No need for extra words... Come on!","sourceKey":"Dialog:context:Wife55_FindDialogue12_2","speaker":"Lulu"},{"number":3,"text":"After so many rounds of your game with the princess, you get into the zone, thinking about your next moves.","sourceKey":"Dialog:context:Wife55_FindDialogue12_3","speaker":null},{"number":4,"text":"Suddenly, you have a brilliant idea and immediately run into the dungeon’s forest to fetch a small and cute slime.","sourceKey":"Dialog:context:Wife55_FindDialogue12_4","speaker":null},{"number":5,"text":"Huh? A monster? Hahaha~ You finally show your weakness! How could I, a princess, possibly bother about such a low-level creature—","sourceKey":"Dialog:context:Wife55_FindDialogue12_5","speaker":"Lulu"},{"number":6,"text":"... Hm?","sourceKey":"Dialog:context:Wife55_FindDialogue12_6","speaker":"Slime"},{"number":7,"text":"—So cute, awww~","sourceKey":"Dialog:context:Wife55_FindDialogue12_7","speaker":"Lulu"},{"number":8,"text":"It’s surprising to see such a small and cute slime! Its voice is so adorable...!","sourceKey":"Dialog:context:Wife55_FindDialogue12_8","speaker":"Lulu"},{"number":9,"text":"And that's not all, Your Highness~ This slime is especially soft!","sourceKey":"Dialog:context:Wife55_FindDialogue12_9","speaker":"{playerName}"},{"number":10,"text":"The feeling of holding it in your arms is amazing!","sourceKey":"Dialog:context:Wife55_FindDialogue12_10","speaker":"{playerName}"},{"number":11,"text":"W-what?!","sourceKey":"Dialog:context:Wife55_FindDialogue12_11","speaker":"Lulu"},{"number":12,"text":"After the sweet surprise, the princess seems to have become mute, unable to say a complete sentence.","sourceKey":"Dialog:context:Wife55_FindDialogue12_12","speaker":null},{"number":13,"text":"Besides holding the slime in her arms and stroking it, the princess doesn’t want to do anything else.","sourceKey":"Dialog:context:Wife55_FindDialogue12_13","speaker":null},{"number":14,"text":"So... naturally, the princess voluntarily lowers her proud head!","sourceKey":"Dialog:context:Wife55_FindDialogue12_14","speaker":null},{"number":15,"text":"Finally, as the princess rubs the cute slime, she tells you some gossip about the palace, smiling pleasantly.","sourceKey":"Dialog:context:Wife55_FindDialogue12_15","speaker":null},{"number":16,"text":"Fourth round—Your Highness the Princess has been defeated again, but at least she got to touch a cute slime!","sourceKey":"Dialog:context:Wife55_FindDialogue12_16","speaker":null},{"number":17,"text":"The princess calls you over, although a little reluctantly.","sourceKey":"Dialog:context:Wife55_FindDialogue12_Text","speaker":null}]},{"id":"FindWife55_13","characterId":"wife_55","step":"13","lines":[{"number":1,"text":"What are you doing standing there? It's raining heavily, come under my umbrella and take cover for a while.","sourceKey":"Dialog:context:Wife55_FindDialogue13_1","speaker":"Lulu"}]},{"id":"FindWife55_14","characterId":"wife_55","step":"14","lines":[{"number":1,"text":"Drakenberg has sent over lots of high food. Even though my country is in debt, they treat me so well. Take some for yourself too. Don't be shy.","sourceKey":"Dialog:context:Wife55_FindDialogue14_1","speaker":"Lulu"}]},{"id":"FindWife55_15","characterId":"wife_55","step":"15","lines":[{"number":1,"text":"Recently, I received a letter from home. Father said that the debt is gradually getting paid off! And the people's lives are getting better too! It's wonderful~","sourceKey":"Dialog:context:Wife55_FindDialogue15_1","speaker":"Lulu"}]},{"id":"FindWife55_16","characterId":"wife_55","step":"16","lines":[{"number":1,"text":"How could this be? No, this can't be!","sourceKey":"Dialog:context:Wife55_FindDialogue16_1","speaker":"Lulu"},{"number":2,"text":"What's wrong? Did something happen?","sourceKey":"Dialog:context:Wife55_FindDialogue16_2","speaker":"{playerName}"},{"number":3,"text":"Oh, you're the one who's been accompanying the princess all this time. That's great, please come and help us!","sourceKey":"Dialog:context:Wife55_FindDialogue16_3","speaker":"Soldier"},{"number":4,"text":"The royal family has already paid part of the debt, and we want to send the princess back, but she insists on staying until the debt is paid off.","sourceKey":"Dialog:context:Wife55_FindDialogue16_4","speaker":"Soldier"},{"number":5,"text":"*Sigh* No matter how we try to persuade her, she insists on serving as collateral, although her family can pay off at any time.","sourceKey":"Dialog:context:Wife55_FindDialogue16_5","speaker":"Soldier"},{"number":6,"text":"Putting that aside, we can’t take the princess now but can’t also keep her here forever...","sourceKey":"Dialog:context:Wife55_FindDialogue16_6","speaker":"Soldier"},{"number":7,"text":"Why do you not take her back with you since your guys’ relationship is so good?!","sourceKey":"Dialog:context:Wife55_FindDialogue16_7","speaker":"Soldier"},{"number":8,"text":"Ah?! Can this be taken so lightly?!","sourceKey":"Dialog:context:Wife55_FindDialogue16_8","speaker":"{playerName}"},{"number":9,"text":"That's settled then! If you have any financial needs, just let us know, we'll provide you with enough money and food!","sourceKey":"Dialog:context:Wife55_FindDialogue16_9","speaker":"Soldier"},{"number":10,"text":"Without realizing it, before you answered, the guards had already assigned you to take the princess back to her family.","sourceKey":"Dialog:context:Wife55_FindDialogue16_10","speaker":null},{"number":11,"text":"Ah? Oh...","sourceKey":"Dialog:context:Wife55_FindDialogue16_11","speaker":"{playerName}"},{"number":12,"text":"Humph, in the end, it fell into your hands... It seems my future life will be filled with test games!","sourceKey":"Dialog:context:Wife55_FindDialogue16_12","speaker":"Lulu"},{"number":13,"text":"Your Highness still remembers the so-called “test games”...","sourceKey":"Dialog:context:Wife55_FindDialogue16_13","speaker":"{playerName}"},{"number":14,"text":"Since I’ll be a guest, I’ll know my place and won’t expect you to treat me as a noble.","sourceKey":"Dialog:context:Wife55_FindDialogue16_14","speaker":"Lulu"},{"number":15,"text":"But! I haven't forgotten what you've done! One day, I will definitely take revenge!","sourceKey":"Dialog:context:Wife55_FindDialogue16_15","speaker":"Lulu"},{"number":16,"text":"Alright then~ As long as you, princess, have that fighting spirit, I'll accompany you!","sourceKey":"Dialog:context:Wife55_FindDialogue16_16","speaker":"{playerName}"},{"number":17,"text":"A large group of guards gathers near the princess.","sourceKey":"Dialog:context:Wife55_FindDialogue16_Text","speaker":null}]},{"id":"FindWife55_After","characterId":"wife_55","step":"After","lines":[{"number":1,"text":"Seeing this scene, I can't help but think of those days... Let's have a competition again!","sourceKey":"Dialog:context:Wife55_FindDialogueAfter_1","speaker":"Lulu"}]}]};
